def _accounting_month_bounds(year: int, month: int) -> tuple[datetime, datetime]:
    start_dt = datetime(year, month, 1)
    end_dt = datetime(year + 1, 1, 1) if month == 12 else datetime(year, month + 1, 1)
    return start_dt, end_dt


async def _get_accounting_close_period(
    session: AsyncSession,
    *,
    fiscal_year: int,
    fiscal_month: int,
) -> Optional[AccountingClosePeriod]:
    return await session.scalar(
        select(AccountingClosePeriod).where(
            AccountingClosePeriod.fiscal_year == fiscal_year,
            AccountingClosePeriod.fiscal_month == fiscal_month,
        )
    )


async def _is_accounting_period_closed(
    session: AsyncSession,
    *,
    fiscal_year: int,
    fiscal_month: int,
) -> bool:
    period = await _get_accounting_close_period(
        session,
        fiscal_year=fiscal_year,
        fiscal_month=fiscal_month,
    )
    return bool(period and (period.status or "").strip().lower() == "closed")


async def _ensure_accounting_period_open(
    session: AsyncSession,
    *,
    fiscal_year: int,
    fiscal_month: int,
    redirect_to: str,
):
    if await _is_accounting_period_closed(session, fiscal_year=fiscal_year, fiscal_month=fiscal_month):
        return RedirectResponse(
            url=_safe_redirect_base(redirect_to, "/admin/contabilidad/cierres")
            + "?error_msg="
            + quote(f"El período {fiscal_year}-{fiscal_month:02d} está cerrado y no acepta cambios contables."),
            status_code=303,
    )
    return None


def _accounting_role(current_empleado: Empleado) -> str:
    return (getattr(current_empleado, "rol", "") or "").strip().lower()


def _can_manage_accounting_structure(current_empleado: Empleado) -> bool:
    role = _accounting_role(current_empleado)
    if role in {"admin", "superadmin", "super_admin"}:
        return True
    return any(
        has_permission(current_empleado, permission)
        for permission in (
            "admin.finanzas.structural",
            "admin.finanzas.close",
            "admin.finanzas.delete",
            "admin.finanzas.reclass",
            "contabilidad.manage_structure",
            "contabilidad.close_periods",
            "contabilidad.delete_polizas",
            "contabilidad.reclassify",
        )
    )


def _can_edit_accounting_headers(current_empleado: Empleado) -> bool:
    role = _accounting_role(current_empleado)
    if role in {"admin", "superadmin", "super_admin"}:
        return True
    return any(
        has_permission(current_empleado, permission)
        for permission in (
            "admin.finanzas.edit_headers",
            "admin.finanzas.structural",
            "contabilidad.edit_headers",
            "contabilidad.manage_structure",
        )
    )


def _ensure_accounting_role_capability(
    current_empleado: Empleado,
    *,
    allowed: bool,
    redirect_to: str,
    message: str,
):
    if allowed:
        return None
    return RedirectResponse(
        url=_safe_redirect_base(redirect_to, "/admin/contabilidad/estado") + "?error_msg=" + quote(message),
        status_code=303,
    )


def _default_accounting_close_checklist_items() -> list[dict[str, str]]:
    return [
        {"task_code": "coi_importado", "label": "COI del período importado y validado", "owner_role": "contabilidad"},
        {"task_code": "banco_conciliado", "label": "Conciliación bancaria sin pendientes críticos", "owner_role": "finanzas"},
        {"task_code": "sin_mappings_pendientes", "label": "Todas las partidas tienen cuenta contable asignada", "owner_role": "contabilidad"},
        {"task_code": "nomina_contabilizada", "label": "Nómina del período contabilizada o confirmada como N/A", "owner_role": "nomina"},
        {"task_code": "cfdi_revisados", "label": "CFDI y soportes revisados para cierre", "owner_role": "fiscal"},
        {"task_code": "paquete_emitido", "label": "Paquete de cierre emitido para despacho / dirección", "owner_role": "contabilidad"},
    ]


async def _ensure_accounting_close_period_record(
    session: AsyncSession,
    *,
    fiscal_year: int,
    fiscal_month: int,
) -> AccountingClosePeriod:
    period = await _get_accounting_close_period(session, fiscal_year=fiscal_year, fiscal_month=fiscal_month)
    if period is not None:
        return period
    period = AccountingClosePeriod(
        id=uuid4(),
        fiscal_year=fiscal_year,
        fiscal_month=fiscal_month,
        status="open",
    )
    session.add(period)
    await session.flush()
    return period


async def _ensure_accounting_close_checklist_seed(
    session: AsyncSession,
    *,
    fiscal_year: int,
    fiscal_month: int,
) -> tuple[AccountingClosePeriod, list[AccountingCloseChecklistItem]]:
    period = await _ensure_accounting_close_period_record(
        session,
        fiscal_year=fiscal_year,
        fiscal_month=fiscal_month,
    )
    existing_items = (
        await session.execute(
            select(AccountingCloseChecklistItem)
            .options(selectinload(AccountingCloseChecklistItem.completed_by))
            .where(AccountingCloseChecklistItem.close_period_id == period.id)
            .order_by(AccountingCloseChecklistItem.label.asc())
        )
    ).scalars().all()
    existing_codes = {item.task_code for item in existing_items}
    created = False
    for template in _default_accounting_close_checklist_items():
        if template["task_code"] in existing_codes:
            continue
        session.add(
            AccountingCloseChecklistItem(
                id=uuid4(),
                close_period_id=period.id,
                task_code=template["task_code"],
                label=template["label"],
                owner_role=template["owner_role"],
                status="pending",
            )
        )
        created = True
    if created:
        await session.flush()
        existing_items = (
            await session.execute(
                select(AccountingCloseChecklistItem)
                .options(selectinload(AccountingCloseChecklistItem.completed_by))
                .where(AccountingCloseChecklistItem.close_period_id == period.id)
                .order_by(AccountingCloseChecklistItem.label.asc())
            )
        ).scalars().all()
    return period, existing_items


def _render_manual_poliza_line_rows(
    cuentas: list[CuentaContable],
    *,
    rows: list[dict[str, Any]],
) -> str:
    cuenta_options = "".join(
        f'<option value="{cuenta.id}" data-code="{escape(cuenta.codigo)}">{escape(cuenta.codigo)} · {escape(cuenta.nombre)}</option>'
        for cuenta in cuentas
    )
    rendered: list[str] = []
    for idx, row in enumerate(rows, start=1):
        cuenta_contable_id = str(row.get("cuenta_contable_id") or "")
        option_markup = "".join(
            f'<option value="{cuenta.id}" data-code="{escape(cuenta.codigo)}" {"selected" if cuenta_contable_id == str(cuenta.id) else ""}>{escape(cuenta.codigo)} · {escape(cuenta.nombre)}</option>'
            for cuenta in cuentas
        )
        rendered.append(
            f"""
            <tr class="manual-line-row">
                <td>{idx}</td>
                <td><input type="text" name="cuenta_codigo" value="{_html_value(row.get('cuenta_codigo'))}" placeholder="Ej. 5100-001"></td>
                <td>
                    <select name="cuenta_contable_id" data-autofill-code="1">
                        <option value="">Cuenta del sistema (opcional)</option>
                        {option_markup or cuenta_options}
                    </select>
                </td>
                <td><input type="text" name="concepto_linea" value="{_html_value(row.get('concepto'))}" placeholder="Concepto de la partida"></td>
                <td><input type="text" name="movimiento_no" value="{_html_value(row.get('movimiento_no'))}" placeholder="Mov."></td>
                <td><input type="number" step="0.01" min="0" name="debe" value="{_html_value(row.get('debe'))}"></td>
                <td><input type="number" step="0.01" min="0" name="haber" value="{_html_value(row.get('haber'))}"></td>
                <td><button type="button" class="button secondary" data-remove-line="1">Quitar</button></td>
            </tr>
            """
        )
    return "".join(rendered)


def _accounting_poliza_snapshot(poliza: AccountingPoliza) -> dict[str, Any]:
    return {
        "id": str(poliza.id),
        "tipo_poliza": poliza.tipo_poliza,
        "numero_poliza": poliza.numero_poliza,
        "fecha_poliza": poliza.fecha_poliza.isoformat() if poliza.fecha_poliza else None,
        "beneficiario_nombre": poliza.beneficiario_nombre,
        "concepto": poliza.concepto,
        "concepto_resumen": poliza.concepto_resumen,
        "origen": poliza.origen,
        "line_count_actual": poliza.line_count_actual,
    }


def _accounting_poliza_line_snapshot(line: AccountingPolizaLine) -> dict[str, Any]:
    return {
        "id": str(line.id),
        "poliza_id": str(line.poliza_id),
        "line_no": line.line_no,
        "cuenta_codigo": line.cuenta_codigo,
        "cuenta_contable_id": str(line.cuenta_contable_id) if line.cuenta_contable_id else None,
        "concepto": line.concepto,
        "movimiento_no": line.movimiento_no,
        "debe": float(line.debe or 0),
        "haber": float(line.haber or 0),
    }


def _accounting_close_period_snapshot(period: AccountingClosePeriod) -> dict[str, Any]:
    return {
        "id": str(period.id),
        "fiscal_year": period.fiscal_year,
        "fiscal_month": period.fiscal_month,
        "status": period.status,
        "notes": period.notes,
        "closed_at": period.closed_at.isoformat() if period.closed_at else None,
        "reopened_at": period.reopened_at.isoformat() if period.reopened_at else None,
    }


async def _record_accounting_audit(
    session: AsyncSession,
    *,
    empleado_id: Optional[UUIDType],
    entity_type: str,
    action: str,
    poliza_id: Optional[UUIDType] = None,
    poliza_line_id: Optional[UUIDType] = None,
    close_period_id: Optional[UUIDType] = None,
    before_state: Optional[dict[str, Any]] = None,
    after_state: Optional[dict[str, Any]] = None,
    details: Optional[dict[str, Any]] = None,
) -> None:
    session.add(
        AccountingAuditLog(
            id=uuid4(),
            empleado_id=empleado_id,
            poliza_id=poliza_id,
            poliza_line_id=poliza_line_id,
            close_period_id=close_period_id,
            entity_type=entity_type,
            action=action,
            before_state=before_state,
            after_state=after_state,
            details=details,
        )
    )


def _next_manual_poliza_number(existing_numbers: list[str], tipo_poliza: str) -> str:
    cleaned = [str(number or "").strip() for number in existing_numbers if str(number or "").strip()]
    if not cleaned:
        return f"{tipo_poliza}-0001"

    def _score(number: str) -> tuple[int, int]:
        match = re.search(r"(\d+)(?!.*\d)", number)
        if not match:
            return (0, 0)
        return (int(match.group(1)), len(match.group(1)))

    best = max(cleaned, key=_score)
    match = re.search(r"(\d+)(?!.*\d)", best)
    if not match:
        return f"{tipo_poliza}-0001"
    width = len(match.group(1))
    next_value = int(match.group(1)) + 1
    return f"{best[:match.start(1)]}{str(next_value).zfill(width)}{best[match.end(1):]}"


def _parse_money_decimal(value: Any, field_label: str) -> Decimal:
    try:
        amount = Decimal(str(value or "0").replace(",", "").strip() or "0")
    except Exception as exc:
        raise ValueError(f"{field_label} no es un importe válido") from exc
    return amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def _build_ingreso_cobrado_line_payload(
    *,
    total_cobrado: Decimal,
    iva_trasladado: Decimal,
    cuenta_banco: CuentaContable,
    cuenta_ingreso: CuentaContable,
    cuenta_iva: Optional[CuentaContable],
    concepto: str,
) -> tuple[list[dict[str, Any]], Decimal]:
    if total_cobrado <= 0:
        raise ValueError("El monto cobrado debe ser mayor a cero")
    if iva_trasladado < 0:
        raise ValueError("El IVA trasladado no puede ser negativo")
    if iva_trasladado >= total_cobrado:
        raise ValueError("El IVA trasladado debe ser menor al monto cobrado")
    if iva_trasladado > 0 and cuenta_iva is None:
        raise ValueError("Selecciona la cuenta de IVA trasladado")

    ingreso_base = (total_cobrado - iva_trasladado).quantize(
        Decimal("0.01"),
        rounding=ROUND_HALF_UP,
    )
    lines = [
        {
            "cuenta_codigo": cuenta_banco.codigo,
            "cuenta_contable_id": cuenta_banco.id,
            "concepto": concepto,
            "movimiento_no": "1",
            "debe": float(total_cobrado),
            "haber": 0.0,
        },
        {
            "cuenta_codigo": cuenta_ingreso.codigo,
            "cuenta_contable_id": cuenta_ingreso.id,
            "concepto": concepto,
            "movimiento_no": "1",
            "debe": 0.0,
            "haber": float(ingreso_base),
        },
    ]
    if iva_trasladado > 0 and cuenta_iva is not None:
        lines.append(
            {
                "cuenta_codigo": cuenta_iva.codigo,
                "cuenta_contable_id": cuenta_iva.id,
                "concepto": f"{concepto} / IVA trasladado",
                "movimiento_no": "1",
                "debe": 0.0,
                "haber": float(iva_trasladado),
            }
        )
    return lines, ingreso_base


