@router.get("/admin/contabilidad/balanza/export")
async def contabilidad_balanza_export(
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
    year: Optional[int] = Query(None),
    month: Optional[int] = Query(None),
    q: str = Query(""),
):
    from openpyxl import Workbook

    now = datetime.utcnow()
    selected_year = year or now.year
    selected_month = month or now.month
    selected_q = (q or "").strip()
    start_dt = datetime(selected_year, selected_month, 1)
    end_dt = datetime(selected_year + 1, 1, 1) if selected_month == 12 else datetime(selected_year, selected_month + 1, 1)
    prior_dt = start_dt

    aux_conditions = [AuxLedgerEntry.fecha.isnot(None), AuxLedgerEntry.fecha >= start_dt, AuxLedgerEntry.fecha < end_dt]
    if selected_q:
        token = f"%{selected_q}%"
        aux_conditions.append(or_(AuxLedgerEntry.cuenta_codigo.ilike(token), AuxLedgerEntry.cuenta_nombre.ilike(token), AuxLedgerEntry.concepto.ilike(token)))

    aux_entries = (
        await session.execute(
            select(AuxLedgerEntry)
            .where(and_(*aux_conditions))
            .order_by(AuxLedgerEntry.cuenta_codigo.asc(), AuxLedgerEntry.fecha.asc(), AuxLedgerEntry.source_row_number.asc())
        )
    ).scalars().all()
    opening_entries = (
        await session.execute(
            select(AuxLedgerEntry)
            .where(AuxLedgerEntry.fecha.isnot(None), AuxLedgerEntry.fecha < prior_dt)
            .order_by(AuxLedgerEntry.cuenta_codigo.asc(), AuxLedgerEntry.fecha.desc(), AuxLedgerEntry.source_row_number.desc())
        )
    ).scalars().all()
    opening_by_code: dict[str, float] = {}
    for entry in opening_entries:
        if entry.cuenta_codigo and entry.cuenta_codigo not in opening_by_code:
            opening_by_code[entry.cuenta_codigo] = float(entry.saldo or entry.saldo_inicial or 0)

    balances: dict[str, dict[str, Any]] = {}
    for entry in aux_entries:
        code = entry.cuenta_codigo or "Sin cuenta"
        bucket = balances.setdefault(code, {"nombre": entry.cuenta_nombre or "", "saldo_inicial": opening_by_code.get(code, float(entry.saldo_inicial or 0)), "debe": 0.0, "haber": 0.0, "saldo_final": 0.0, "movimientos": 0})
        bucket["debe"] += float(entry.debe or 0)
        bucket["haber"] += float(entry.haber or 0)
        bucket["movimientos"] += 1
        bucket["saldo_final"] = float(entry.saldo or 0)

    wb = Workbook()
    ws = wb.active
    ws.title = "Balanza"
    ws.append(["Cuenta", "Nombre", "Saldo inicial", "Debe", "Haber", "Saldo final", "Movimientos"])
    for code, stats in sorted(balances.items()):
        ws.append([code, stats["nombre"], stats["saldo_inicial"], stats["debe"], stats["haber"], stats["saldo_final"] if stats["movimientos"] else stats["saldo_inicial"], stats["movimientos"]])
    output = io.BytesIO()
    wb.save(output)
    output.seek(0)
    return Response(
        content=output.getvalue(),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename=\"balanza_{selected_year}_{selected_month:02d}.xlsx\"'},
    )


@router.get("/admin/contabilidad/balanza/export.pdf")
async def contabilidad_balanza_export_pdf(
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
    year: Optional[int] = Query(None),
    month: Optional[int] = Query(None),
    q: str = Query(""),
):
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.pdfgen import canvas

    now = datetime.utcnow()
    selected_year = year or now.year
    selected_month = month or now.month
    selected_q = (q or "").strip()
    start_dt = datetime(selected_year, selected_month, 1)
    end_dt = datetime(selected_year + 1, 1, 1) if selected_month == 12 else datetime(selected_year, selected_month + 1, 1)
    prior_dt = start_dt
    aux_conditions = [AuxLedgerEntry.fecha.isnot(None), AuxLedgerEntry.fecha >= start_dt, AuxLedgerEntry.fecha < end_dt]
    if selected_q:
        token = f"%{selected_q}%"
        aux_conditions.append(or_(AuxLedgerEntry.cuenta_codigo.ilike(token), AuxLedgerEntry.cuenta_nombre.ilike(token), AuxLedgerEntry.concepto.ilike(token)))

    aux_entries = (
        await session.execute(
            select(AuxLedgerEntry)
            .where(and_(*aux_conditions))
            .order_by(AuxLedgerEntry.cuenta_codigo.asc(), AuxLedgerEntry.fecha.asc(), AuxLedgerEntry.source_row_number.asc())
        )
    ).scalars().all()
    opening_entries = (
        await session.execute(
            select(AuxLedgerEntry)
            .where(AuxLedgerEntry.fecha.isnot(None), AuxLedgerEntry.fecha < prior_dt)
            .order_by(AuxLedgerEntry.cuenta_codigo.asc(), AuxLedgerEntry.fecha.desc(), AuxLedgerEntry.source_row_number.desc())
        )
    ).scalars().all()
    opening_by_code: dict[str, float] = {}
    for entry in opening_entries:
        if entry.cuenta_codigo and entry.cuenta_codigo not in opening_by_code:
            opening_by_code[entry.cuenta_codigo] = float(entry.saldo or entry.saldo_inicial or 0)

    balances: dict[str, dict[str, Any]] = {}
    for entry in aux_entries:
        code = entry.cuenta_codigo or "Sin cuenta"
        bucket = balances.setdefault(code, {"nombre": entry.cuenta_nombre or "", "saldo_inicial": opening_by_code.get(code, float(entry.saldo_inicial or 0)), "debe": 0.0, "haber": 0.0, "saldo_final": 0.0, "movimientos": 0})
        bucket["debe"] += float(entry.debe or 0)
        bucket["haber"] += float(entry.haber or 0)
        bucket["movimientos"] += 1
        bucket["saldo_final"] = float(entry.saldo or 0)

    output = io.BytesIO()
    page_width, page_height = landscape(A4)
    pdf = canvas.Canvas(output, pagesize=(page_width, page_height))
    y = page_height - 40
    pdf.setFont("Helvetica-Bold", 12)
    pdf.drawString(30, y, f"Balanza de comprobacion {selected_year}-{selected_month:02d}")
    y -= 18
    pdf.setFont("Helvetica", 8)
    pdf.drawString(30, y, f"Filtro q={selected_q or '—'}")
    totals = {
        "saldo_inicial": sum(stats["saldo_inicial"] for stats in balances.values()),
        "debe": sum(stats["debe"] for stats in balances.values()),
        "haber": sum(stats["haber"] for stats in balances.values()),
        "saldo_final": sum((stats["saldo_final"] if stats["movimientos"] else stats["saldo_inicial"]) for stats in balances.values()),
    }
    pdf.drawString(210, y, f"Saldo inicial: {format_currency(totals['saldo_inicial'])}")
    pdf.drawString(390, y, f"Debe/Haber: {format_currency(totals['debe'])} / {format_currency(totals['haber'])}")
    pdf.drawString(620, y, f"Saldo final: {format_currency(totals['saldo_final'])}")
    y -= 20
    headers = ["Cuenta", "Nombre", "Saldo inicial", "Debe", "Haber", "Saldo final"]
    positions = [30, 120, 360, 470, 560, 650]
    for idx, header in enumerate(headers):
        pdf.drawString(positions[idx], y, header)
    y -= 12
    pdf.line(30, y, page_width - 30, y)
    y -= 12
    for code, stats in sorted(balances.items()):
        if y < 40:
            pdf.showPage()
            y = page_height - 40
        values = [
            code,
            (stats["nombre"] or "")[:34],
            f'{stats["saldo_inicial"]:,.2f}',
            f'{stats["debe"]:,.2f}',
            f'{stats["haber"]:,.2f}',
            f'{(stats["saldo_final"] if stats["movimientos"] else stats["saldo_inicial"]):,.2f}',
        ]
        for idx, value in enumerate(values):
            pdf.drawString(positions[idx], y, str(value))
        y -= 12
    if y < 120:
        pdf.showPage()
        y = page_height - 40
    y -= 16
    pdf.setFont("Helvetica", 10)
    pdf.drawString(50, y, "Elaboró")
    pdf.drawString(320, y, "Revisó")
    pdf.drawString(590, y, "Autorizó")
    y -= 30
    pdf.line(40, y, 220, y)
    pdf.line(310, y, 490, y)
    pdf.line(580, y, 760, y)
    pdf.save()
    output.seek(0)
    return Response(
        content=output.getvalue(),
        media_type="application/pdf",
        headers={"Content-Disposition": f'attachment; filename=\"balanza_{selected_year}_{selected_month:02d}.pdf\"'},
    )


@router.get("/admin/contabilidad/estado", response_class=HTMLResponse)
async def contabilidad_estado_mes_view(
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
    year: Optional[int] = Query(None),
    month: Optional[int] = Query(None),
) -> str:
    now = datetime.utcnow()
    selected_year = year or now.year
    selected_month = month or now.month
    start_dt = datetime(selected_year, selected_month, 1)
    end_dt = datetime(selected_year + 1, 1, 1) if selected_month == 12 else datetime(selected_year, selected_month + 1, 1)

    polizas = (
        await session.execute(
            select(AccountingPoliza)
            .options(selectinload(AccountingPoliza.lines))
            .where(AccountingPoliza.fecha_poliza.isnot(None), AccountingPoliza.fecha_poliza >= start_dt, AccountingPoliza.fecha_poliza < end_dt)
        )
    ).scalars().all()
    aux_entries = (
        await session.execute(
            select(AuxLedgerEntry)
            .where(AuxLedgerEntry.fecha.isnot(None), AuxLedgerEntry.fecha >= start_dt, AuxLedgerEntry.fecha < end_dt)
        )
    ).scalars().all()
    bank_movements = (
        await session.execute(
            select(BankMovement)
            .where(BankMovement.fecha >= start_dt, BankMovement.fecha < end_dt)
        )
    ).scalars().all()
    imports = (
        await session.execute(
            select(AccountingImportRun)
            .where(AccountingImportRun.started_at >= start_dt, AccountingImportRun.started_at < end_dt)
            .order_by(AccountingImportRun.started_at.desc())
        )
    ).scalars().all()

    poliza_debe = sum(sum(float(line.debe or 0) for line in poliza.lines) for poliza in polizas)
    poliza_haber = sum(sum(float(line.haber or 0) for line in poliza.lines) for poliza in polizas)
    aux_debe = sum(float(entry.debe or 0) for entry in aux_entries)
    aux_haber = sum(float(entry.haber or 0) for entry in aux_entries)
    bank_amount = sum(float(movement.importe or 0) for movement in bank_movements)
    reco = {"high": 0, "medium": 0, "unmatched": 0}
    for movement in bank_movements:
        state = (movement.conciliacion_estado or "unmatched").lower()
        reco[state] = reco.get(state, 0) + 1

    source_rows: dict[str, dict[str, Any]] = {}
    for run in imports:
        bucket = source_rows.setdefault(
            run.source_type or "otro",
            {"count": 0, "filename": run.filename, "mode": run.mode, "status": run.status},
        )
        bucket["count"] += 1
    import_table_rows = "".join(
        f"<tr><td>{escape(source)}</td><td>{stats['count']}</td><td>{escape(stats['filename'])}</td><td>{escape(stats['mode'])}</td><td>{escape(stats['status'])}</td></tr>"
        for source, stats in sorted(source_rows.items())
    )

    html = f"""
    <!DOCTYPE html>
    <html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Estado contable del mes</title>
    <style>
    body {{ font-family: Arial, sans-serif; background:#f6f8fb; margin:0; padding:20px; }}
    .container {{ max-width: 1500px; margin:0 auto; }}
    .card {{ background:#fff; border:1px solid #e5e7eb; border-radius:10px; padding:16px; margin-bottom:16px; }}
    .toolbar {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:12px; }}
    input {{ width:100%; padding:8px 10px; border:1px solid #d1d5db; border-radius:8px; box-sizing:border-box; }}
    .summary {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:12px; }}
    .summary .box {{ background:#111827; color:#fff; border-radius:10px; padding:14px; }}
    .summary .label {{ font-size:12px; opacity:.8; text-transform:uppercase; }}
    .summary .value {{ font-size:22px; font-weight:700; margin-top:6px; }}
    table {{ width:100%; border-collapse:collapse; }}
    th, td {{ padding:10px 12px; border-bottom:1px solid #e5e7eb; text-align:left; font-size:13px; vertical-align:top; }}
    th {{ background:#f3f4f6; }}
    .button {{ display:inline-block; padding:10px 14px; border-radius:8px; text-decoration:none; background:#111827; color:#fff; border:none; cursor:pointer; }}
    .button.secondary {{ background:#e5e7eb; color:#111827; }}
    .muted {{ color:#6b7280; font-size:13px; }}
    </style></head>
    <body><div class="container">{render_top_navigation(current_empleado, "contabilidad")}{_contabilidad_subnav("estado")}
        <div class="card">
            <h1 style="margin:0 0 8px 0;">Estado contable del mes</h1>
            <p class="muted" style="margin:0 0 16px 0;">Vista ejecutiva del período para revisar COI, auxiliar, banco e integración de conciliación antes de cierre.</p>
            <form method="GET" action="/admin/contabilidad/estado" class="toolbar">
                <div><label>Año</label><input type="number" name="year" value="{selected_year}"></div>
                <div><label>Mes</label><input type="number" min="1" max="12" name="month" value="{selected_month}"></div>
                <div style="display:flex;align-items:end;gap:8px;"><button type="submit" class="button">Filtrar</button><a href="/admin/contabilidad/estado" class="button secondary">Limpiar</a></div>
            </form>
        </div>
        <div class="summary">
            <div class="box"><div class="label">Pólizas COI</div><div class="value">{len(polizas)}</div></div>
            <div class="box"><div class="label">COI Debe / Haber</div><div class="value">{format_currency(poliza_debe)} / {format_currency(poliza_haber)}</div></div>
            <div class="box"><div class="label">Auxiliar Debe / Haber</div><div class="value">{format_currency(aux_debe)} / {format_currency(aux_haber)}</div></div>
            <div class="box"><div class="label">Banco movimientos</div><div class="value">{len(bank_movements)}</div></div>
            <div class="box"><div class="label">Banco importe</div><div class="value">{format_currency(bank_amount)}</div></div>
            <div class="box"><div class="label">Conciliación H/M/U</div><div class="value">{reco.get("high", 0)} / {reco.get("medium", 0)} / {reco.get("unmatched", 0)}</div></div>
        </div>
        <div class="card">
            <h2 style="margin:0 0 12px 0;">Atajos del período</h2>
            <div style="display:flex;gap:8px;flex-wrap:wrap;">
                <a class="button secondary" href="/admin/contabilidad/coi?year={selected_year}&month={selected_month}">Ver COI</a>
                <a class="button secondary" href="/admin/contabilidad/mayor?year={selected_year}&month={selected_month}">Ver mayor</a>
                <a class="button secondary" href="/admin/contabilidad/balanza?year={selected_year}&month={selected_month}">Ver balanza</a>
                <a class="button secondary" href="/admin/contabilidad/conciliacion?year={selected_year}&month={selected_month}">Ver conciliación</a>
            </div>
        </div>
        <div class="card">
            <h2 style="margin:0 0 12px 0;">Imports del período</h2>
            <table>
                <thead><tr><th>Origen</th><th>Corridas</th><th>Archivo ejemplo</th><th>Modo</th><th>Status</th></tr></thead>
                <tbody>{import_table_rows if import_table_rows else '<tr><td colspan="5" class="muted">Sin imports contables en este período.</td></tr>'}</tbody>
            </table>
        </div>
    </div></body></html>
    """
    return html


@router.post("/admin/contabilidad/coi/lineas/{line_id}/cuenta")
async def contabilidad_coi_line_set_account(
    line_id: UUIDType,
    cuenta_contable_id: UUIDType = Form(...),
    apply_same_code: Optional[str] = Form(None),
    redirect_to: str = Form("/admin/contabilidad/coi"),
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
):
    line = (
        await session.execute(
            select(AccountingPolizaLine)
            .options(selectinload(AccountingPolizaLine.poliza))
            .where(AccountingPolizaLine.id == line_id)
        )
    ).scalar_one_or_none()
    if line is None:
        raise HTTPException(status_code=404, detail="No existe esa partida contable.")
    if line.poliza and line.poliza.fecha_poliza:
        guard = await _ensure_accounting_period_open(
            session,
            fiscal_year=line.poliza.fecha_poliza.year,
            fiscal_month=line.poliza.fecha_poliza.month,
            redirect_to=redirect_to,
        )
        if guard is not None:
            return guard

    before_snapshot = _accounting_poliza_line_snapshot(line)
    cuenta = await session.scalar(
        select(CuentaContable).where(
            CuentaContable.id == cuenta_contable_id,
            CuentaContable.activo == True,
        )
    )
    if cuenta is None:
        return RedirectResponse(
            url=_safe_redirect_base(redirect_to, "/admin/contabilidad/coi") + "?error_msg=" + quote("La cuenta contable seleccionada no existe o está inactiva"),
            status_code=303,
        )

    if _truthy_form(apply_same_code):
        capability_guard = _ensure_accounting_role_capability(
            current_empleado,
            allowed=_can_manage_accounting_structure(current_empleado),
            redirect_to=redirect_to,
            message="La propagación masiva por código COI requiere permisos estructurales de contabilidad.",
        )
        if capability_guard is not None:
            return capability_guard

    line.cuenta_contable_id = cuenta.id
    if _truthy_form(apply_same_code):
        same_code_lines = (
            await session.execute(
                select(AccountingPolizaLine).where(AccountingPolizaLine.cuenta_codigo == line.cuenta_codigo)
            )
        ).scalars().all()
        for item in same_code_lines:
            item.cuenta_contable_id = cuenta.id

        same_code_aux = (
            await session.execute(
                select(AuxLedgerEntry).where(AuxLedgerEntry.cuenta_codigo == line.cuenta_codigo)
            )
        ).scalars().all()
        for item in same_code_aux:
            item.cuenta_contable_id = cuenta.id

    await _record_accounting_audit(
        session,
        empleado_id=current_empleado.id,
        entity_type="poliza_line",
        action="set_line_account",
        poliza_id=line.poliza_id,
        poliza_line_id=line.id,
        before_state=before_snapshot,
        after_state={
            **_accounting_poliza_line_snapshot(line),
            "cuenta_contable_id": str(cuenta.id),
        },
        details={
            "apply_same_code": _truthy_form(apply_same_code),
            "cuenta_codigo": line.cuenta_codigo,
        },
    )
    await session.commit()
    success_text = f"Cuenta contable asignada a {line.cuenta_codigo}"
    if _truthy_form(apply_same_code):
        success_text += " y propagada al mismo código"
    return RedirectResponse(
        url=_safe_redirect_base(redirect_to, "/admin/contabilidad/coi") + "?success_msg=" + quote(success_text),
        status_code=303,
    )


@router.get("/admin/contabilidad/cierres", response_class=HTMLResponse)
async def contabilidad_cierres_view(
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
    year: Optional[int] = Query(None),
    month: Optional[int] = Query(None),
) -> str:
    success_msg = request.query_params.get("success_msg", "")
    error_msg = request.query_params.get("error_msg", "")
    selected_year = year or datetime.utcnow().year
    selected_month = month or datetime.utcnow().month

    close_rows = (
        await session.execute(
            select(AccountingClosePeriod)
            .where(AccountingClosePeriod.fiscal_year == selected_year)
            .order_by(AccountingClosePeriod.fiscal_month.asc())
        )
    ).scalars().all()
    close_map = {period.fiscal_month: period for period in close_rows}
    can_manage_structure = _can_manage_accounting_structure(current_empleado)
    checklist_period, checklist_items = await _ensure_accounting_close_checklist_seed(
        session,
        fiscal_year=selected_year,
        fiscal_month=selected_month,
    )

    month_rows = []
    for fiscal_month in range(1, 13):
        start_dt, end_dt = _accounting_month_bounds(selected_year, fiscal_month)
        polizas = (
            await session.execute(
                select(AccountingPoliza)
                .options(selectinload(AccountingPoliza.lines))
                .where(
                    AccountingPoliza.fecha_poliza.isnot(None),
                    AccountingPoliza.fecha_poliza >= start_dt,
                    AccountingPoliza.fecha_poliza < end_dt,
                )
            )
        ).scalars().all()
        total_debe = sum(sum(float(line.debe or 0) for line in poliza.lines) for poliza in polizas)
        total_haber = sum(sum(float(line.haber or 0) for line in poliza.lines) for poliza in polizas)
        unbalanced_polizas = sum(
            1 for poliza in polizas if round(sum(float(line.debe or 0) for line in poliza.lines) - sum(float(line.haber or 0) for line in poliza.lines), 2) != 0
        )
        unmatched_bank = int(
            (
                await session.execute(
                    select(func.count(BankMovement.id)).where(
                        BankMovement.fecha >= start_dt,
                        BankMovement.fecha < end_dt,
                        BankMovement.conciliacion_estado == "unmatched",
                    )
                )
            ).scalar()
            or 0
        )
        unmapped_lines = int(
            (
                await session.execute(
                    select(func.count(AccountingPolizaLine.id))
                    .join(AccountingPoliza, AccountingPoliza.id == AccountingPolizaLine.poliza_id)
                    .where(
                        AccountingPoliza.fecha_poliza.isnot(None),
                        AccountingPoliza.fecha_poliza >= start_dt,
                        AccountingPoliza.fecha_poliza < end_dt,
                        AccountingPolizaLine.cuenta_contable_id.is_(None),
                    )
                )
            ).scalar()
            or 0
        )
        close_blockers = []
        if unbalanced_polizas:
            close_blockers.append(f"{unbalanced_polizas} pólizas descuadradas")
        if unmatched_bank:
            close_blockers.append(f"{unmatched_bank} movimientos bancarios sin conciliar")
        if unmapped_lines:
            close_blockers.append(f"{unmapped_lines} partidas sin cuenta contable")
        close_period = close_map.get(fiscal_month)
        is_closed = bool(close_period and (close_period.status or "").strip().lower() == "closed")
        close_action = (
            f"""
            <form method="POST" action="/admin/contabilidad/cierres/{selected_year}/{fiscal_month}/reabrir" style="display:inline-flex;gap:8px;align-items:center;">
                <input type="hidden" name="return_to" value="/admin/contabilidad/cierres?year={selected_year}">
                <button type="submit" class="button secondary" {'disabled' if not can_manage_structure else ''}>Reabrir</button>
            </form>
            """
            if is_closed
            else
            f"""
            <form method="POST" action="/admin/contabilidad/cierres/{selected_year}/{fiscal_month}/cerrar" style="display:inline-flex;gap:8px;align-items:center;">
                <input type="hidden" name="return_to" value="/admin/contabilidad/cierres?year={selected_year}">
                <button type="submit" class="button" {'disabled' if close_blockers or not can_manage_structure else ''}>Cerrar</button>
            </form>
            """
        )
        month_rows.append(
            f"""
            <tr>
                <td>{selected_year}-{fiscal_month:02d}</td>
                <td>{'Cerrado' if is_closed else 'Abierto'}</td>
                <td>{len(polizas)}</td>
                <td>{format_currency(total_debe)}</td>
                <td>{format_currency(total_haber)}</td>
                <td>{format_currency(total_debe - total_haber)}</td>
                <td>{unbalanced_polizas}</td>
                <td>{unmatched_bank}</td>
                <td>{unmapped_lines}</td>
                <td>{escape(close_period.closed_at.date().isoformat() if close_period and close_period.closed_at else '-')}</td>
                <td>{escape(close_period.closed_by.nombre if close_period and close_period.closed_by else '-')}</td>
                <td>{escape("; ".join(close_blockers) if close_blockers else "Listo para cierre")}</td>
                <td>{close_action}</td>
            </tr>
            """
        )

    html = f"""
    <!DOCTYPE html>
    <html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Cierres contables</title>
    <style>
    body {{ font-family: Arial, sans-serif; background:#f6f8fb; margin:0; padding:20px; }}
    .container {{ max-width: 1540px; margin:0 auto; }}
    .card {{ background:#fff; border:1px solid #e5e7eb; border-radius:10px; padding:16px; margin-bottom:16px; }}
    .toolbar {{ display:flex; gap:12px; flex-wrap:wrap; align-items:end; }}
    input {{ padding:8px 10px; border:1px solid #d1d5db; border-radius:8px; }}
    table {{ width:100%; border-collapse:collapse; }}
    th, td {{ padding:10px 12px; border-bottom:1px solid #e5e7eb; text-align:left; font-size:13px; vertical-align:top; }}
    th {{ background:#f3f4f6; }}
    .button {{ display:inline-block; padding:10px 14px; border-radius:8px; text-decoration:none; background:#111827; color:#fff; border:none; cursor:pointer; }}
    .button.secondary {{ background:#e5e7eb; color:#111827; }}
    .muted {{ color:#6b7280; font-size:13px; }}
    </style></head>
    <body><div class="container">{render_top_navigation(current_empleado, "contabilidad")}{_contabilidad_subnav("cierres")}
        <div class="card">
            <h1 style="margin:0 0 8px 0;">Cierres mensuales</h1>
            <p class="muted" style="margin:0 0 16px 0;">Candado contable del período. Si un mes está cerrado, no se permiten cambios en pólizas manuales ni reclasificaciones contables del mes.</p>
            {'' if can_manage_structure else '<div style="background:#fffbeb;color:#92400e;border:1px solid #fde68a;border-radius:10px;padding:12px 14px;margin:0 0 16px 0;"><strong>Permisos limitados:</strong> puedes revisar el estado del cierre, pero el cierre/reapertura del período requiere permisos estructurales de contabilidad.</div>'}
            {f'<div style="background:#d1fae5;color:#065f46;border:1px solid #a7f3d0;border-radius:10px;padding:12px 14px;margin:0 0 16px 0;"><strong>✅ Éxito:</strong> {escape(success_msg)}</div>' if success_msg else ''}
            {f'<div style="background:#fee2e2;color:#991b1b;border:1px solid #fecaca;border-radius:10px;padding:12px 14px;margin:0 0 16px 0;"><strong>❌ Error:</strong> {escape(error_msg)}</div>' if error_msg else ''}
            <form method="GET" action="/admin/contabilidad/cierres" class="toolbar">
                <div><label>Año</label><input type="number" name="year" value="{selected_year}"></div>
                <div><label>Mes checklist</label><input type="number" name="month" min="1" max="12" value="{selected_month}"></div>
                <div style="display:flex;gap:8px;align-items:end;flex-wrap:wrap;"><button type="submit" class="button secondary">Actualizar vista</button><a href="/admin/contabilidad/cierres/export?year={selected_year}&month={selected_month}" class="button secondary">Exportar paquete de cierre</a><a href="/admin/contabilidad/cierres/export.zip?year={selected_year}&month={selected_month}" class="button secondary">Exportar ZIP</a></div>
            </form>
        </div>
        <div class="card">
            <table>
                <thead><tr><th>Período</th><th>Status</th><th>Pólizas</th><th>Debe</th><th>Haber</th><th>Diferencia</th><th>Pólizas descuadradas</th><th>Banco unmatched</th><th>Partidas sin mapping</th><th>Cerrado en</th><th>Cerró</th><th>Validación</th><th>Acción</th></tr></thead>
                <tbody>{''.join(month_rows)}</tbody>
            </table>
        </div>
        <div class="card">
            <div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;">
                <div>
                    <h2 style="margin:0 0 6px 0;">Checklist de cierre {selected_year}-{selected_month:02d}</h2>
                    <p class="muted" style="margin:0;">Control de tareas del período antes del cierre formal.</p>
                </div>
                <div class="muted">Estado período: {escape((checklist_period.status or 'open').lower())}</div>
            </div>
            <table style="margin-top:14px;">
                <thead><tr><th>Tarea</th><th>Responsable</th><th>Status</th><th>Notas</th><th>Completó</th><th>Acción</th></tr></thead>
                <tbody>{
                    ''.join(
                        f'''
                        <tr>
                            <td>{escape(item.label)}</td>
                            <td>{escape(item.owner_role or '-')}</td>
                            <td>{escape(item.status or 'pending')}</td>
                            <td>{escape((item.notes or '')[:140] or '-')}</td>
                            <td>{escape(item.completed_by.nombre if item.completed_by else '-')}</td>
                            <td>
                                <form method="POST" action="/admin/contabilidad/cierres/checklist/{item.id}" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
                                    <input type="hidden" name="return_to" value="/admin/contabilidad/cierres?year={selected_year}&month={selected_month}">
                                    <input type="hidden" name="status" value="{ 'pending' if (item.status or 'pending') == 'completed' else 'completed' }">
                                    <input type="text" name="notes" value="{_html_value(item.notes)}" placeholder="Notas / evidencia" style="min-width:220px;">
                                    <button type="submit" class="button secondary">{'Reabrir tarea' if (item.status or 'pending') == 'completed' else 'Completar'}</button>
                                </form>
                            </td>
                        </tr>
                        '''
                        for item in checklist_items
                    )
                }</tbody>
            </table>
        </div>
    </div></body></html>
    """
    return html


@router.get("/admin/contabilidad/auditoria", response_class=HTMLResponse)
async def contabilidad_auditoria_view(
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
    year: Optional[int] = Query(None),
    month: Optional[int] = Query(None),
    action: str = Query("all"),
) -> str:
    now = datetime.utcnow()
    selected_year = year or now.year
    selected_month = month or now.month
    selected_action = (action or "all").strip()
    start_dt, end_dt = _accounting_month_bounds(selected_year, selected_month)

    conditions = [
        AccountingAuditLog.created_at >= start_dt,
        AccountingAuditLog.created_at < end_dt,
    ]
    if selected_action != "all":
        conditions.append(AccountingAuditLog.action == selected_action)

    logs = (
        await session.execute(
            select(AccountingAuditLog)
            .options(
                selectinload(AccountingAuditLog.empleado),
                selectinload(AccountingAuditLog.poliza),
                selectinload(AccountingAuditLog.close_period),
            )
            .where(and_(*conditions))
            .order_by(AccountingAuditLog.created_at.desc())
        )
    ).scalars().all()

    action_values = (
        await session.execute(
            select(AccountingAuditLog.action).distinct().order_by(AccountingAuditLog.action.asc())
        )
    ).scalars().all()
    action_options = ['<option value="all">Todas</option>'] + [
        f'<option value="{escape(value)}" {_selected_attr(selected_action, value)}>{escape(value)}</option>'
        for value in action_values if value
    ]

    rows = "".join(
        f"""
        <tr>
            <td>{escape(log.created_at.isoformat(sep=' ', timespec='seconds') if log.created_at else '-')}</td>
            <td>{escape(log.action)}</td>
            <td>{escape(log.entity_type)}</td>
            <td>{escape(log.poliza.numero_poliza if log.poliza else (f"{log.close_period.fiscal_year}-{log.close_period.fiscal_month:02d}" if log.close_period else '-'))}</td>
            <td>{escape(log.empleado.nombre if log.empleado else '-')}</td>
            <td><code>{escape(json.dumps(log.details or {}, ensure_ascii=False)[:180])}</code></td>
        </tr>
        """
        for log in logs
    )

    html = f"""
    <!DOCTYPE html>
    <html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Auditoría contable</title>
    <style>
    body {{ font-family: Arial, sans-serif; background:#f6f8fb; margin:0; padding:20px; }}
    .container {{ max-width: 1540px; margin:0 auto; }}
    .card {{ background:#fff; border:1px solid #e5e7eb; border-radius:10px; padding:16px; margin-bottom:16px; }}
    .toolbar {{ display:flex; gap:12px; flex-wrap:wrap; align-items:end; }}
    input, select {{ padding:8px 10px; border:1px solid #d1d5db; border-radius:8px; }}
    table {{ width:100%; border-collapse:collapse; }}
    th, td {{ padding:10px 12px; border-bottom:1px solid #e5e7eb; text-align:left; font-size:13px; vertical-align:top; }}
    th {{ background:#f3f4f6; }}
    .button {{ display:inline-block; padding:10px 14px; border-radius:8px; text-decoration:none; background:#111827; color:#fff; border:none; cursor:pointer; }}
    .button.secondary {{ background:#e5e7eb; color:#111827; }}
    .muted {{ color:#6b7280; font-size:13px; }}
    code {{ font-size:12px; white-space:pre-wrap; }}
    </style></head>
    <body><div class="container">{render_top_navigation(current_empleado, "contabilidad")}{_contabilidad_subnav("auditoria")}
        <div class="card">
            <h1 style="margin:0 0 8px 0;">Auditoría contable</h1>
            <p class="muted" style="margin:0 0 16px 0;">Bitácora de cambios sobre pólizas manuales, reclasificaciones y cierres del período.</p>
            <form method="GET" action="/admin/contabilidad/auditoria" class="toolbar">
                <div><label>Año</label><input type="number" name="year" value="{selected_year}"></div>
                <div><label>Mes</label><input type="number" min="1" max="12" name="month" value="{selected_month}"></div>
                <div><label>Acción</label><select name="action">{''.join(action_options)}</select></div>
                <div><button type="submit" class="button">Filtrar</button></div>
            </form>
        </div>
        <div class="card">
            <table>
                <thead><tr><th>Fecha</th><th>Acción</th><th>Entidad</th><th>Referencia</th><th>Usuario</th><th>Detalle</th></tr></thead>
                <tbody>{rows if rows else '<tr><td colspan="6" class="muted">Sin eventos auditados para este período.</td></tr>'}</tbody>
            </table>
        </div>
    </div></body></html>
    """
    return html


@router.post("/admin/contabilidad/cierres/checklist/{item_id}")
async def contabilidad_cierre_checklist_update(
    item_id: UUIDType,
    status: str = Form("completed"),
    notes: Optional[str] = Form(None),
    return_to: Optional[str] = Form(None),
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
):
    item = await session.scalar(
        select(AccountingCloseChecklistItem)
        .options(selectinload(AccountingCloseChecklistItem.close_period))
        .where(AccountingCloseChecklistItem.id == item_id)
    )
    if item is None:
        raise HTTPException(status_code=404, detail="No existe esa tarea de checklist.")

    normalized_status = "completed" if (status or "").strip().lower() == "completed" else "pending"
    before_snapshot = {
        "task_code": item.task_code,
        "label": item.label,
        "status": item.status,
        "notes": item.notes,
    }
    item.status = normalized_status
    item.notes = _clean_optional_text(notes)
    if normalized_status == "completed":
        item.completed_at = datetime.utcnow()
        item.completed_by_empleado_id = current_empleado.id
    else:
        item.completed_at = None
        item.completed_by_empleado_id = None

    await _record_accounting_audit(
        session,
        empleado_id=current_empleado.id,
        entity_type="close_checklist_item",
        action="update_close_checklist_item",
        close_period_id=item.close_period_id,
        before_state=before_snapshot,
        after_state={
            "task_code": item.task_code,
            "label": item.label,
            "status": item.status,
            "notes": item.notes,
        },
        details={
            "fiscal_year": item.close_period.fiscal_year if item.close_period else None,
            "fiscal_month": item.close_period.fiscal_month if item.close_period else None,
        },
    )
    await session.commit()
    return RedirectResponse(
        url=_safe_redirect_base(return_to, "/admin/contabilidad/cierres") + "?success_msg=" + quote("Checklist de cierre actualizado"),
        status_code=303,
    )


@router.post("/admin/contabilidad/cierres/{fiscal_year}/{fiscal_month}/cerrar")
async def contabilidad_cierre_cerrar(
    fiscal_year: int,
    fiscal_month: int,
    return_to: Optional[str] = Form(None),
    notes: Optional[str] = Form(None),
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
):
    capability_guard = _ensure_accounting_role_capability(
        current_empleado,
        allowed=_can_manage_accounting_structure(current_empleado),
        redirect_to=return_to or f"/admin/contabilidad/cierres?year={fiscal_year}",
        message="Tu perfil puede revisar cierres, pero no cerrar períodos contables.",
    )
    if capability_guard is not None:
        return capability_guard
    start_dt, end_dt = _accounting_month_bounds(fiscal_year, fiscal_month)
    polizas = (
        await session.execute(
            select(AccountingPoliza)
            .options(selectinload(AccountingPoliza.lines))
            .where(
                AccountingPoliza.fecha_poliza.isnot(None),
                AccountingPoliza.fecha_poliza >= start_dt,
                AccountingPoliza.fecha_poliza < end_dt,
            )
        )
    ).scalars().all()
    if any(round(sum(float(line.debe or 0) for line in poliza.lines) - sum(float(line.haber or 0) for line in poliza.lines), 2) != 0 for poliza in polizas):
        return RedirectResponse(
            url=_safe_redirect_base(return_to, f"/admin/contabilidad/cierres?year={fiscal_year}") + "?error_msg=" + quote("No se puede cerrar el período: existen pólizas descuadradas."),
            status_code=303,
        )
    unmatched_bank = int(
        (
            await session.execute(
                select(func.count(BankMovement.id)).where(
                    BankMovement.fecha >= start_dt,
                    BankMovement.fecha < end_dt,
                    BankMovement.conciliacion_estado == "unmatched",
                )
            )
        ).scalar()
        or 0
    )
    if unmatched_bank:
        return RedirectResponse(
            url=_safe_redirect_base(return_to, f"/admin/contabilidad/cierres?year={fiscal_year}") + "?error_msg=" + quote(f"No se puede cerrar el período: hay {unmatched_bank} movimientos bancarios sin conciliar."),
            status_code=303,
        )
    unmapped_lines = int(
        (
            await session.execute(
                select(func.count(AccountingPolizaLine.id))
                .join(AccountingPoliza, AccountingPoliza.id == AccountingPolizaLine.poliza_id)
                .where(
                    AccountingPoliza.fecha_poliza.isnot(None),
                    AccountingPoliza.fecha_poliza >= start_dt,
                    AccountingPoliza.fecha_poliza < end_dt,
                    AccountingPolizaLine.cuenta_contable_id.is_(None),
                )
            )
        ).scalar()
        or 0
    )
    if unmapped_lines:
        return RedirectResponse(
            url=_safe_redirect_base(return_to, f"/admin/contabilidad/cierres?year={fiscal_year}") + "?error_msg=" + quote(f"No se puede cerrar el período: hay {unmapped_lines} partidas sin cuenta contable asignada."),
            status_code=303,
        )
    period, checklist_items = await _ensure_accounting_close_checklist_seed(
        session,
        fiscal_year=fiscal_year,
        fiscal_month=fiscal_month,
    )
    pending_checklist = [item.label for item in checklist_items if (item.status or "pending").strip().lower() != "completed"]
    if pending_checklist:
        return RedirectResponse(
            url=_safe_redirect_base(return_to, f"/admin/contabilidad/cierres?year={fiscal_year}&month={fiscal_month}") + "?error_msg=" + quote(f"No se puede cerrar el período: faltan tareas del checklist ({len(pending_checklist)})."),
            status_code=303,
        )

    before_snapshot = _accounting_close_period_snapshot(period)
    if before_snapshot["status"] == "open" and not before_snapshot["closed_at"]:
        before_snapshot = None
    period.status = "closed"
    period.notes = _clean_optional_text(notes) or period.notes
    period.closed_at = datetime.utcnow()
    period.closed_by_empleado_id = current_empleado.id
    await _record_accounting_audit(
        session,
        empleado_id=current_empleado.id,
        entity_type="close_period",
        action="close_period",
        close_period_id=period.id,
        before_state=before_snapshot,
        after_state=_accounting_close_period_snapshot(period),
        details={
            "fiscal_year": fiscal_year,
            "fiscal_month": fiscal_month,
        },
    )
    await session.commit()
    return RedirectResponse(
        url=_safe_redirect_base(return_to, f"/admin/contabilidad/cierres?year={fiscal_year}") + "?success_msg=" + quote(f"Período {fiscal_year}-{fiscal_month:02d} cerrado"),
        status_code=303,
    )


@router.post("/admin/contabilidad/cierres/{fiscal_year}/{fiscal_month}/reabrir")
async def contabilidad_cierre_reabrir(
    fiscal_year: int,
    fiscal_month: int,
    return_to: Optional[str] = Form(None),
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
):
    capability_guard = _ensure_accounting_role_capability(
        current_empleado,
        allowed=_can_manage_accounting_structure(current_empleado),
        redirect_to=return_to or f"/admin/contabilidad/cierres?year={fiscal_year}",
        message="Tu perfil puede revisar cierres, pero no reabrir períodos contables.",
    )
    if capability_guard is not None:
        return capability_guard
    period = await _get_accounting_close_period(session, fiscal_year=fiscal_year, fiscal_month=fiscal_month)
    if period is None:
        period = AccountingClosePeriod(
            id=uuid4(),
            fiscal_year=fiscal_year,
            fiscal_month=fiscal_month,
            status="open",
            reopened_at=datetime.utcnow(),
            reopened_by_empleado_id=current_empleado.id,
        )
        session.add(period)
        before_snapshot = None
    else:
        before_snapshot = _accounting_close_period_snapshot(period)
        period.status = "open"
        period.reopened_at = datetime.utcnow()
        period.reopened_by_empleado_id = current_empleado.id
    await _record_accounting_audit(
        session,
        empleado_id=current_empleado.id,
        entity_type="close_period",
        action="reopen_period",
        close_period_id=period.id,
        before_state=before_snapshot,
        after_state=_accounting_close_period_snapshot(period),
        details={
            "fiscal_year": fiscal_year,
            "fiscal_month": fiscal_month,
        },
    )
    await session.commit()
    return RedirectResponse(
        url=_safe_redirect_base(return_to, f"/admin/contabilidad/cierres?year={fiscal_year}") + "?success_msg=" + quote(f"Período {fiscal_year}-{fiscal_month:02d} reabierto"),
        status_code=303,
    )


@router.get("/admin/contabilidad/cierres/export")
async def contabilidad_cierre_export_package(
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
    year: Optional[int] = Query(None),
    month: Optional[int] = Query(None),
):
    from openpyxl import Workbook

    now = datetime.utcnow()
    selected_year = year or now.year
    selected_month = month or now.month
    start_dt, end_dt = _accounting_month_bounds(selected_year, selected_month)

    close_period = await _get_accounting_close_period(
        session,
        fiscal_year=selected_year,
        fiscal_month=selected_month,
    )
    _, checklist_items = await _ensure_accounting_close_checklist_seed(
        session,
        fiscal_year=selected_year,
        fiscal_month=selected_month,
    )
    polizas = (
        await session.execute(
            select(AccountingPoliza)
            .options(selectinload(AccountingPoliza.lines))
            .where(
                AccountingPoliza.fecha_poliza.isnot(None),
                AccountingPoliza.fecha_poliza >= start_dt,
                AccountingPoliza.fecha_poliza < end_dt,
            )
            .order_by(AccountingPoliza.fecha_poliza.asc(), AccountingPoliza.tipo_poliza.asc(), AccountingPoliza.numero_poliza.asc())
        )
    ).scalars().all()
    diario_lines = (
        await session.execute(
            select(AccountingPolizaLine)
            .join(AccountingPoliza, AccountingPoliza.id == AccountingPolizaLine.poliza_id)
            .options(
                selectinload(AccountingPolizaLine.poliza),
                selectinload(AccountingPolizaLine.cuenta_contable),
            )
            .where(
                AccountingPoliza.fecha_poliza.isnot(None),
                AccountingPoliza.fecha_poliza >= start_dt,
                AccountingPoliza.fecha_poliza < end_dt,
            )
            .order_by(
                AccountingPoliza.fecha_poliza.asc(),
                AccountingPoliza.tipo_poliza.asc(),
                AccountingPoliza.numero_poliza.asc(),
                AccountingPolizaLine.line_no.asc(),
            )
        )
    ).scalars().all()
    aux_entries = (
        await session.execute(
            select(AuxLedgerEntry)
            .where(
                AuxLedgerEntry.fecha.isnot(None),
                AuxLedgerEntry.fecha >= start_dt,
                AuxLedgerEntry.fecha < end_dt,
            )
            .order_by(AuxLedgerEntry.cuenta_codigo.asc(), AuxLedgerEntry.fecha.asc(), AuxLedgerEntry.source_row_number.asc())
        )
    ).scalars().all()
    opening_entries = (
        await session.execute(
            select(AuxLedgerEntry)
            .where(
                AuxLedgerEntry.fecha.isnot(None),
                AuxLedgerEntry.fecha < start_dt,
            )
            .order_by(AuxLedgerEntry.cuenta_codigo.asc(), AuxLedgerEntry.fecha.desc(), AuxLedgerEntry.source_row_number.desc())
        )
    ).scalars().all()
    bank_movements = (
        await session.execute(
            select(BankMovement)
            .options(selectinload(BankMovement.proveedor_cliente))
            .where(BankMovement.fecha >= start_dt, BankMovement.fecha < end_dt)
            .order_by(BankMovement.fecha.asc(), BankMovement.created_at.asc())
        )
    ).scalars().all()
    audit_logs = (
        await session.execute(
            select(AccountingAuditLog)
            .options(selectinload(AccountingAuditLog.empleado), selectinload(AccountingAuditLog.poliza))
            .where(
                AccountingAuditLog.created_at >= start_dt,
                AccountingAuditLog.created_at < end_dt,
            )
            .order_by(AccountingAuditLog.created_at.desc())
        )
    ).scalars().all()
    imports = (
        await session.execute(
            select(AccountingImportRun)
            .where(
                AccountingImportRun.started_at >= start_dt,
                AccountingImportRun.started_at < end_dt,
            )
            .order_by(AccountingImportRun.started_at.desc())
        )
    ).scalars().all()

    poliza_debe = sum(sum(float(line.debe or 0) for line in poliza.lines) for poliza in polizas)
    poliza_haber = sum(sum(float(line.haber or 0) for line in poliza.lines) for poliza in polizas)
    unbalanced_polizas = sum(
        1
        for poliza in polizas
        if round(
            sum(float(line.debe or 0) for line in poliza.lines)
            - sum(float(line.haber or 0) for line in poliza.lines),
            2,
        )
        != 0
    )
    unmatched_bank = sum(1 for movement in bank_movements if (movement.conciliacion_estado or "unmatched").lower() == "unmatched")
    unmapped_lines = sum(1 for line in diario_lines if not line.cuenta_contable_id)

    opening_by_code: dict[str, float] = {}
    for entry in opening_entries:
        if entry.cuenta_codigo and entry.cuenta_codigo not in opening_by_code:
            opening_by_code[entry.cuenta_codigo] = float(entry.saldo or entry.saldo_inicial or 0)

    balances: dict[str, dict[str, Any]] = {}
    for entry in aux_entries:
        code = entry.cuenta_codigo or "Sin cuenta"
        bucket = balances.setdefault(
            code,
            {
                "nombre": entry.cuenta_nombre or "",
                "saldo_inicial": opening_by_code.get(code, float(entry.saldo_inicial or 0)),
                "debe": 0.0,
                "haber": 0.0,
                "saldo_final": 0.0,
                "movimientos": 0,
            },
        )
        bucket["debe"] += float(entry.debe or 0)
        bucket["haber"] += float(entry.haber or 0)
        bucket["movimientos"] += 1
        bucket["saldo_final"] = float(entry.saldo or 0)

    workbook = Workbook()

    ws_resumen = workbook.active
    ws_resumen.title = "Resumen"
    ws_resumen.append(["Campo", "Valor"])
    ws_resumen.append(["Periodo", f"{selected_year}-{selected_month:02d}"])
    ws_resumen.append(["Estado cierre", (close_period.status if close_period else "open")])
    ws_resumen.append(["Cerrado en", close_period.closed_at.isoformat(sep=" ", timespec="seconds") if close_period and close_period.closed_at else ""])
    ws_resumen.append(["Cerró", close_period.closed_by.nombre if close_period and close_period.closed_by else ""])
    ws_resumen.append(["Pólizas", len(polizas)])
    ws_resumen.append(["Debe", poliza_debe])
    ws_resumen.append(["Haber", poliza_haber])
    ws_resumen.append(["Diferencia", poliza_debe - poliza_haber])
    ws_resumen.append(["Pólizas descuadradas", unbalanced_polizas])
    ws_resumen.append(["Banco unmatched", unmatched_bank])
    ws_resumen.append(["Partidas sin mapping", unmapped_lines])
    ws_resumen.append(["Exports generados en", datetime.utcnow().isoformat(sep=" ", timespec="seconds")])

    ws_checklist = workbook.create_sheet("Checklist")
    ws_checklist.append(["Tarea", "Responsable", "Status", "Notas", "Completado en", "Completó"])
    for item in checklist_items:
        ws_checklist.append(
            [
                item.label,
                item.owner_role or "",
                item.status or "",
                item.notes or "",
                item.completed_at.isoformat(sep=" ", timespec="seconds") if item.completed_at else "",
                item.completed_by.nombre if item.completed_by else "",
            ]
        )

    ws_diario = workbook.create_sheet("Diario")
    ws_diario.append(["Fecha", "Tipo", "Poliza", "Beneficiario", "Cuenta COI", "Cuenta sistema", "Concepto", "Debe", "Haber", "Origen"])
    for line in diario_lines:
        poliza = line.poliza
        ws_diario.append(
            [
                poliza.fecha_poliza.date().isoformat() if poliza and poliza.fecha_poliza else "",
                poliza.tipo_poliza if poliza else "",
                poliza.numero_poliza if poliza else "",
                poliza.beneficiario_nombre if poliza else "",
                line.cuenta_codigo or "",
                line.cuenta_contable.nombre if line.cuenta_contable else "",
                line.concepto or (poliza.concepto_resumen if poliza else "") or "",
                float(line.debe or 0),
                float(line.haber or 0),
                poliza.origen if poliza else "",
            ]
        )

    ws_balanza = workbook.create_sheet("Balanza")
    ws_balanza.append(["Cuenta", "Nombre", "Saldo inicial", "Debe", "Haber", "Saldo final", "Movimientos"])
    for code, stats in sorted(balances.items()):
        ws_balanza.append(
            [
                code,
                stats["nombre"],
                stats["saldo_inicial"],
                stats["debe"],
                stats["haber"],
                stats["saldo_final"] if stats["movimientos"] else stats["saldo_inicial"],
                stats["movimientos"],
            ]
        )

    ws_conciliacion = workbook.create_sheet("Conciliacion")
    ws_conciliacion.append(["Fecha", "Descripcion", "Referencia", "Proveedor", "Importe", "Estado", "Auxiliar", "Poliza", "Gasto"])
    for movement in bank_movements:
        ws_conciliacion.append(
            [
                movement.fecha.isoformat() if movement.fecha else "",
                movement.descripcion or "",
                movement.referencia or "",
                movement.proveedor_cliente.nombre if movement.proveedor_cliente else "",
                float(movement.importe or 0),
                movement.conciliacion_estado or "",
                str(movement.matched_aux_entry_id or ""),
                str(movement.matched_poliza_id or ""),
                str(movement.matched_expense_id or ""),
            ]
        )

    ws_auditoria = workbook.create_sheet("Auditoria")
    ws_auditoria.append(["Fecha", "Accion", "Entidad", "Referencia", "Usuario", "Detalle"])
    for log in audit_logs:
        ws_auditoria.append(
            [
                log.created_at.isoformat(sep=" ", timespec="seconds") if log.created_at else "",
                log.action or "",
                log.entity_type or "",
                log.poliza.numero_poliza if log.poliza else "",
                log.empleado.nombre if log.empleado else "",
                json.dumps(log.details or {}, ensure_ascii=False),
            ]
        )

    ws_imports = workbook.create_sheet("Imports")
    ws_imports.append(["Fecha", "Origen", "Archivo", "Modo", "Status"])
    for run in imports:
        ws_imports.append(
            [
                run.started_at.isoformat(sep=" ", timespec="seconds") if run.started_at else "",
                run.source_type or "",
                run.filename or "",
                run.mode or "",
                run.status or "",
            ]
        )

    output = io.BytesIO()
    workbook.save(output)
    output.seek(0)
    return Response(
        content=output.getvalue(),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="cierre_contable_{selected_year}_{selected_month:02d}.xlsx"'},
    )


@router.get("/admin/contabilidad/cierres/export.zip")
async def contabilidad_cierre_export_zip(
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
    year: Optional[int] = Query(None),
    month: Optional[int] = Query(None),
):
    import zipfile

    now = datetime.utcnow()
    selected_year = year or now.year
    selected_month = month or now.month
    xlsx_response = await contabilidad_cierre_export_package(
        session=session,
        current_empleado=current_empleado,
        year=selected_year,
        month=selected_month,
    )
    diario_pdf = await contabilidad_diario_export_pdf(
        session=session,
        current_empleado=current_empleado,
        year=selected_year,
        month=selected_month,
        tipo="all",
        q="",
    )
    balanza_pdf = await contabilidad_balanza_export_pdf(
        session=session,
        current_empleado=current_empleado,
        year=selected_year,
        month=selected_month,
        q="",
    )
    output = io.BytesIO()
    with zipfile.ZipFile(output, mode="w", compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr(
            f"cierre_contable_{selected_year}_{selected_month:02d}.xlsx",
            xlsx_response.body,
        )
        archive.writestr(
            f"diario_{selected_year}_{selected_month:02d}.pdf",
            diario_pdf.body,
        )
        archive.writestr(
            f"balanza_{selected_year}_{selected_month:02d}.pdf",
            balanza_pdf.body,
        )
        archive.writestr(
            "README.txt",
            (
                f"Paquete de cierre {selected_year}-{selected_month:02d}\n"
                f"Generado: {datetime.utcnow().isoformat(sep=' ', timespec='seconds')}\n"
                "Incluye: resumen+diario+balanza+conciliacion+auditoria+checklist en XLSX, mas PDF de diario y balanza.\n"
            ),
        )
    output.seek(0)
    return Response(
        content=output.getvalue(),
        media_type="application/zip",
        headers={"Content-Disposition": f'attachment; filename="cierre_contable_{selected_year}_{selected_month:02d}.zip"'},
    )


@router.get("/admin/contabilidad/reclasificacion", response_class=HTMLResponse)
async def contabilidad_reclasificacion_view(
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
    year: Optional[int] = Query(None),
    month: Optional[int] = Query(None),
    cuenta_codigo: str = Query(""),
    target_account_id: Optional[UUIDType] = Query(None),
    include_aux: Optional[str] = Query("1"),
):
    now = datetime.utcnow()
    selected_year = year or now.year
    selected_month = month or now.month
    selected_code = (cuenta_codigo or "").strip()
    include_aux_flag = str(include_aux or "1").strip() in {"1", "true", "on", "yes"}
    start_dt, end_dt = _accounting_month_bounds(selected_year, selected_month)
    can_manage_structure = _can_manage_accounting_structure(current_empleado)

    cuentas = (
        await session.execute(
            select(CuentaContable)
            .where(CuentaContable.activo == True)
            .order_by(CuentaContable.codigo.asc())
        )
    ).scalars().all()
    cuenta_options = ['<option value="">Selecciona cuenta destino</option>'] + [
        f'<option value="{cuenta.id}" {_selected_attr(str(target_account_id or ""), str(cuenta.id))}>{escape(cuenta.codigo)} · {escape(cuenta.nombre)}</option>'
        for cuenta in cuentas
    ]
    target_account = cuenta_map = None
    if target_account_id:
        target_account = next((cuenta for cuenta in cuentas if cuenta.id == target_account_id), None)

    preview_lines: list[AccountingPolizaLine] = []
    preview_aux: list[AuxLedgerEntry] = []
    current_mappings: set[str] = set()
    if selected_code:
        preview_lines = (
            await session.execute(
                select(AccountingPolizaLine)
                .join(AccountingPoliza, AccountingPoliza.id == AccountingPolizaLine.poliza_id)
                .options(selectinload(AccountingPolizaLine.poliza), selectinload(AccountingPolizaLine.cuenta_contable))
                .where(
                    AccountingPoliza.fecha_poliza.isnot(None),
                    AccountingPoliza.fecha_poliza >= start_dt,
                    AccountingPoliza.fecha_poliza < end_dt,
                    AccountingPolizaLine.cuenta_codigo == selected_code,
                )
                .order_by(AccountingPoliza.fecha_poliza.asc(), AccountingPoliza.numero_poliza.asc(), AccountingPolizaLine.line_no.asc())
            )
        ).scalars().all()
        if include_aux_flag:
            preview_aux = (
                await session.execute(
                    select(AuxLedgerEntry)
                    .options(selectinload(AuxLedgerEntry.cuenta_contable))
                    .where(
                        AuxLedgerEntry.fecha.isnot(None),
                        AuxLedgerEntry.fecha >= start_dt,
                        AuxLedgerEntry.fecha < end_dt,
                        AuxLedgerEntry.cuenta_codigo == selected_code,
                    )
                    .order_by(AuxLedgerEntry.fecha.asc(), AuxLedgerEntry.source_row_number.asc())
                )
            ).scalars().all()
        current_mappings = {
            f"{line.cuenta_contable.codigo} · {line.cuenta_contable.nombre}"
            for line in preview_lines
            if line.cuenta_contable
        }
        current_mappings.update(
            f"{entry.cuenta_contable.codigo} · {entry.cuenta_contable.nombre}"
            for entry in preview_aux
            if entry.cuenta_contable
        )

    line_rows = "".join(
        f"""
        <tr>
            <td>{escape(line.poliza.fecha_poliza.date().isoformat() if line.poliza and line.poliza.fecha_poliza else "-")}</td>
            <td>{escape(line.poliza.numero_poliza if line.poliza else "-")}</td>
            <td>{escape(line.concepto or "-")}</td>
            <td>{escape(line.cuenta_contable.nombre if line.cuenta_contable else "Sin mapping")}</td>
            <td>{format_currency(float(line.debe or 0))}</td>
            <td>{format_currency(float(line.haber or 0))}</td>
        </tr>
        """
        for line in preview_lines[:50]
    )
    aux_rows = "".join(
        f"""
        <tr>
            <td>{escape(entry.fecha.isoformat() if entry.fecha else "-")}</td>
            <td>{escape(entry.concepto or "-")}</td>
            <td>{escape(entry.cuenta_contable.nombre if entry.cuenta_contable else "Sin mapping")}</td>
            <td>{format_currency(float(entry.debe or 0))}</td>
            <td>{format_currency(float(entry.haber or 0))}</td>
        </tr>
        """
        for entry in preview_aux[:50]
    )

    html = f"""
    <!DOCTYPE html>
    <html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reclasificación masiva</title>
    <style>
    body {{ font-family: Arial, sans-serif; background:#f6f8fb; margin:0; padding:20px; }}
    .container {{ max-width: 1540px; margin:0 auto; }}
    .card {{ background:#fff; border:1px solid #e5e7eb; border-radius:10px; padding:16px; margin-bottom:16px; }}
    .grid {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(220px,1fr)); gap:12px; }}
    input, select {{ width:100%; padding:8px 10px; border:1px solid #d1d5db; border-radius:8px; box-sizing:border-box; }}
    table {{ width:100%; border-collapse:collapse; }}
    th, td {{ padding:10px 12px; border-bottom:1px solid #e5e7eb; text-align:left; font-size:13px; vertical-align:top; }}
    th {{ background:#f3f4f6; }}
    .button {{ display:inline-block; padding:10px 14px; border-radius:8px; text-decoration:none; background:#111827; color:#fff; border:none; cursor:pointer; }}
    .button.secondary {{ background:#e5e7eb; color:#111827; }}
    .summary {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:12px; }}
    .summary .box {{ background:#111827; color:#fff; border-radius:10px; padding:14px; }}
    .summary .label {{ font-size:12px; opacity:.8; text-transform:uppercase; }}
    .summary .value {{ font-size:22px; font-weight:700; margin-top:6px; }}
    .muted {{ color:#6b7280; font-size:13px; }}
    </style></head>
    <body><div class="container">{render_top_navigation(current_empleado, "contabilidad")}{_contabilidad_subnav("reclasificacion")}
        <div class="card">
            <h1 style="margin:0 0 8px 0;">Reclasificación masiva</h1>
            <p class="muted" style="margin:0 0 16px 0;">Preview controlado por período y código COI antes de actualizar líneas contables y, si quieres, auxiliar del mismo período.</p>
            {'' if can_manage_structure else '<div style="background:#fffbeb;color:#92400e;border:1px solid #fde68a;border-radius:10px;padding:12px 14px;margin:0 0 16px 0;"><strong>Permisos limitados:</strong> puedes revisar el impacto, pero aplicar reclasificaciones masivas requiere permisos estructurales de contabilidad.</div>'}
            {f'<div style="background:#d1fae5;color:#065f46;border:1px solid #a7f3d0;border-radius:10px;padding:12px 14px;margin:0 0 16px 0;"><strong>✅ Éxito:</strong> {escape(request.query_params.get("success_msg", ""))}</div>' if request.query_params.get("success_msg") else ''}
            {f'<div style="background:#fee2e2;color:#991b1b;border:1px solid #fecaca;border-radius:10px;padding:12px 14px;margin:0 0 16px 0;"><strong>❌ Error:</strong> {escape(request.query_params.get("error_msg", ""))}</div>' if request.query_params.get("error_msg") else ''}
            <form method="GET" action="/admin/contabilidad/reclasificacion" class="grid">
                <div><label>Año</label><input type="number" name="year" value="{selected_year}"></div>
                <div><label>Mes</label><input type="number" min="1" max="12" name="month" value="{selected_month}"></div>
                <div><label>Código COI</label><input type="text" name="cuenta_codigo" value="{_html_value(selected_code)}" placeholder="Ej. 5100-001"></div>
                <div><label>Cuenta destino</label><select name="target_account_id">{''.join(cuenta_options)}</select></div>
                <div style="display:flex;align-items:end;gap:10px;"><label style="display:flex;gap:8px;align-items:center;"><input type="checkbox" name="include_aux" value="1" {'checked' if include_aux_flag else ''}> incluir auxiliar</label></div>
                <div style="display:flex;align-items:end;gap:8px;"><button type="submit" class="button">Preview</button><a href="/admin/contabilidad/reclasificacion" class="button secondary">Limpiar</a></div>
            </form>
        </div>
        <div class="card">
            <div class="summary">
                <div class="box"><div class="label">Código</div><div class="value">{escape(selected_code or "—")}</div></div>
                <div class="box"><div class="label">Partidas COI</div><div class="value">{len(preview_lines)}</div></div>
                <div class="box"><div class="label">Auxiliar</div><div class="value">{len(preview_aux)}</div></div>
                <div class="box"><div class="label">Destino</div><div class="value">{escape(target_account.codigo if target_account else "—")}</div></div>
            </div>
            <p class="muted" style="margin:12px 0 0 0;">Mappings actuales detectados: {escape(", ".join(sorted(current_mappings)) if current_mappings else "Sin mapping actual")}</p>
        </div>
        <div class="card">
            <form method="POST" action="/admin/contabilidad/reclasificacion/aplicar" onsubmit="return confirm('Se actualizarán las partidas del período seleccionado.');">
                <input type="hidden" name="year" value="{selected_year}">
                <input type="hidden" name="month" value="{selected_month}">
                <input type="hidden" name="cuenta_codigo" value="{_html_value(selected_code)}">
                <input type="hidden" name="target_account_id" value="{_html_value(target_account_id)}">
                <input type="hidden" name="include_aux" value="{'1' if include_aux_flag else '0'}">
                <button type="submit" class="button" {'disabled' if (not selected_code or not target_account_id or not preview_lines or not can_manage_structure) else ''}>Aplicar reclasificación</button>
                <span class="muted" style="margin-left:10px;">Se audita el cambio y respeta el candado del período.</span>
            </form>
        </div>
        <div class="card">
            <h2 style="margin:0 0 12px 0;">Preview de partidas COI</h2>
            <table>
                <thead><tr><th>Fecha</th><th>Póliza</th><th>Concepto</th><th>Cuenta actual</th><th>Debe</th><th>Haber</th></tr></thead>
                <tbody>{line_rows if line_rows else '<tr><td colspan="6" class="muted">Sin partidas para este código en el período.</td></tr>'}</tbody>
            </table>
        </div>
        <div class="card">
            <h2 style="margin:0 0 12px 0;">Preview de auxiliar</h2>
            <table>
                <thead><tr><th>Fecha</th><th>Concepto</th><th>Cuenta actual</th><th>Debe</th><th>Haber</th></tr></thead>
                <tbody>{aux_rows if aux_rows else '<tr><td colspan="5" class="muted">Sin movimientos auxiliares para este código en el período.</td></tr>'}</tbody>
            </table>
        </div>
    </div></body></html>
    """
    return html


@router.post("/admin/contabilidad/reclasificacion/aplicar")
async def contabilidad_reclasificacion_apply(
    year: int = Form(...),
    month: int = Form(...),
    cuenta_codigo: str = Form(...),
    target_account_id: UUIDType = Form(...),
    include_aux: Optional[str] = Form("1"),
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
):
    redirect_base = f"/admin/contabilidad/reclasificacion?year={year}&month={month}&cuenta_codigo={quote((cuenta_codigo or '').strip())}&target_account_id={target_account_id}&include_aux={quote(str(include_aux or '1'))}"
    capability_guard = _ensure_accounting_role_capability(
        current_empleado,
        allowed=_can_manage_accounting_structure(current_empleado),
        redirect_to=redirect_base,
        message="Tu perfil puede revisar reclasificaciones, pero no aplicar cambios masivos.",
    )
    if capability_guard is not None:
        return capability_guard

    selected_code = (cuenta_codigo or "").strip()
    if not selected_code:
        return RedirectResponse(url=redirect_base + "&error_msg=" + quote("Falta el código COI a reclasificar"), status_code=303)
    start_dt, end_dt = _accounting_month_bounds(year, month)
    open_guard = await _ensure_accounting_period_open(
        session,
        fiscal_year=year,
        fiscal_month=month,
        redirect_to=redirect_base,
    )
    if open_guard is not None:
        return open_guard

    target_account = await session.scalar(
        select(CuentaContable).where(
            CuentaContable.id == target_account_id,
            CuentaContable.activo == True,
        )
    )
    if target_account is None:
        return RedirectResponse(url=redirect_base + "&error_msg=" + quote("La cuenta destino no existe o está inactiva"), status_code=303)

    lines = (
        await session.execute(
            select(AccountingPolizaLine)
            .join(AccountingPoliza, AccountingPoliza.id == AccountingPolizaLine.poliza_id)
            .where(
                AccountingPoliza.fecha_poliza.isnot(None),
                AccountingPoliza.fecha_poliza >= start_dt,
                AccountingPoliza.fecha_poliza < end_dt,
                AccountingPolizaLine.cuenta_codigo == selected_code,
            )
        )
    ).scalars().all()
    if not lines:
        return RedirectResponse(url=redirect_base + "&error_msg=" + quote("No hay partidas COI para ese código en el período"), status_code=303)

    include_aux_flag = str(include_aux or "1").strip() in {"1", "true", "on", "yes"}
    aux_entries: list[AuxLedgerEntry] = []
    if include_aux_flag:
        aux_entries = (
            await session.execute(
                select(AuxLedgerEntry).where(
                    AuxLedgerEntry.fecha.isnot(None),
                    AuxLedgerEntry.fecha >= start_dt,
                    AuxLedgerEntry.fecha < end_dt,
                    AuxLedgerEntry.cuenta_codigo == selected_code,
                )
            )
        ).scalars().all()

    distinct_polizas = {line.poliza_id for line in lines if line.poliza_id}
    before_snapshot = {
        "fiscal_year": year,
        "fiscal_month": month,
        "cuenta_codigo": selected_code,
        "line_count": len(lines),
        "aux_count": len(aux_entries),
        "target_account_id": str(target_account.id),
        "target_account_codigo": target_account.codigo,
    }
    for line in lines:
        line.cuenta_contable_id = target_account.id
    for entry in aux_entries:
        entry.cuenta_contable_id = target_account.id

    await _record_accounting_audit(
        session,
        empleado_id=current_empleado.id,
        entity_type="poliza_line",
        action="bulk_reclassify_period_code",
        before_state=before_snapshot,
        after_state={
            **before_snapshot,
            "poliza_count": len(distinct_polizas),
            "include_aux": include_aux_flag,
        },
        details={
            "fiscal_year": year,
            "fiscal_month": month,
            "cuenta_codigo": selected_code,
            "target_account_id": str(target_account.id),
            "target_account_codigo": target_account.codigo,
            "target_account_nombre": target_account.nombre,
            "line_count": len(lines),
            "aux_count": len(aux_entries),
            "include_aux": include_aux_flag,
        },
    )
    await session.commit()
    return RedirectResponse(
        url=redirect_base + "&success_msg=" + quote(f"Reclasificación aplicada a {len(lines)} partidas y {len(aux_entries)} movimientos auxiliares"),
        status_code=303,
    )


