@router.post("/admin/nomina/beneficios/{rule_id}")
async def nomina_beneficios_update(
    rule_id: UUIDType,
    isr_requires_generality: Optional[str] = Form(None),
    isr_requires_documented_plan: Optional[str] = Form(None),
    isr_requires_authorized_delivery_channel: Optional[str] = Form(None),
    sbc_requires_generality: Optional[str] = Form(None),
    sbc_requires_documented_plan: Optional[str] = Form(None),
    sbc_requires_employee_copay_percent_at_least: Optional[str] = Form(None),
    classification_warning: Optional[str] = Form(None),
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = require_admin_finanzas(),
):
    """Update rule payload flags for current payroll benefit treatment."""
    rule = await session.get(PayrollConceptRule, rule_id)
    if not rule:
        raise HTTPException(status_code=404, detail="Regla no encontrada")

    payload = dict(rule.payload_json or {})
    isr_treatment = dict(payload.get("isr_treatment") or {})
    sbc_treatment = dict(payload.get("sbc_treatment") or {})

    isr_treatment["requires_generality"] = _truthy_form(isr_requires_generality)
    isr_treatment["requires_documented_plan"] = _truthy_form(isr_requires_documented_plan)
    isr_treatment["requires_authorized_delivery_channel"] = _truthy_form(isr_requires_authorized_delivery_channel)
    warning_text = (classification_warning or "").strip()
    if warning_text:
        isr_treatment["classification_warning"] = warning_text
    else:
        isr_treatment.pop("classification_warning", None)

    sbc_treatment["requires_generality"] = _truthy_form(sbc_requires_generality)
    sbc_treatment["requires_documented_plan"] = _truthy_form(sbc_requires_documented_plan)
    copay_raw = (sbc_requires_employee_copay_percent_at_least or "").strip()
    if copay_raw:
        try:
            sbc_treatment["requires_employee_copay_percent_at_least"] = float(copay_raw)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail="Copago mínimo inválido") from exc
    else:
        sbc_treatment.pop("requires_employee_copay_percent_at_least", None)

    payload["isr_treatment"] = isr_treatment
    payload["sbc_treatment"] = sbc_treatment
    rule.payload_json = payload
    await session.commit()
    return RedirectResponse(
        url="/admin/nomina/beneficios?success_msg=" + quote("Flags actualizados correctamente"),
        status_code=303,
    )

def set_db_session_maker(session_maker):
    """Set the database session maker for user routes."""
    global _db_session_maker
    _db_session_maker = session_maker

async def get_db_session() -> AsyncSession:
    """Dependency to get database session."""
    if _db_session_maker is None:
        raise RuntimeError("Database session maker not set. Call set_db_session_maker() first.")
    async with _db_session_maker() as session:
        yield session


def is_valid_uuid(value: str) -> bool:
    """Check if a string is a valid UUID."""
    if not value or not isinstance(value, str):
        return False
    try:
        UUIDType(value)
        return True
    except (ValueError, TypeError):
        return False


def _normalize_name_for_similarity(name: Optional[str]) -> str:
    if not name:
        return ""
    decomposed = unicodedata.normalize("NFKD", name)
    without_accents = "".join(
        character
        for character in decomposed
        if not unicodedata.combining(character)
    )
    without_punctuation = re.sub(r"[^\w\s]", "", without_accents).replace(
        "_", ""
    )
    return " ".join(without_punctuation.strip().lower().split())


def _token_set_jaccard(a: str, b: str) -> float:
    if not a or not b:
        return 0.0
    tokens_a = set(a.split())
    tokens_b = set(b.split())
    if not tokens_a or not tokens_b:
        return 0.0
    intersection = tokens_a & tokens_b
    union = tokens_a | tokens_b
    if not union:
        return 0.0
    return len(intersection) / len(union)


def _empleado_proveedor_name_similarity(empleado_nombre: Optional[str], proveedor_nombre: Optional[str]) -> float:
    norm_emp = _normalize_name_for_similarity(empleado_nombre)
    norm_prov = _normalize_name_for_similarity(proveedor_nombre)
    if not norm_emp or not norm_prov:
        return 0.0
    if norm_emp == norm_prov:
        return 1.0
    ratio = SequenceMatcher(None, norm_emp, norm_prov).ratio()
    jaccard = _token_set_jaccard(norm_emp, norm_prov)
    # Weighted combination to give some robustness to word order / extra tokens
    return 0.7 * ratio + 0.3 * jaccard


async def _get_matching_bank_accounts_for_empleado(
    session: AsyncSession,
    empleado: Empleado,
    threshold: float = _EMPLEADO_PROVEEDOR_NAME_SIMILARITY_THRESHOLD,
    limit: int = 50,
):
    """
    Return a list of (ProveedorCliente, similarity) that look like bank accounts for this empleado.
    """
    empleado_nombre = empleado.nombre if empleado else None
    empleado_id = getattr(empleado, "id", None)
    if not empleado_nombre or empleado_id is None:
        return []

    exact_result = await session.execute(
        select(ProveedorCliente).where(
            and_(
                ProveedorCliente.activo == True,
                ProveedorCliente.tipo == "empleado",
                ProveedorCliente.empleado_id == empleado_id,
                or_(
                    ProveedorCliente.banco.isnot(None),
                    ProveedorCliente.cuenta_clabe.isnot(None),
                    ProveedorCliente.cuenta_bancaria.isnot(None),
                ),
            )
        )
    )
    exact_accounts = list(exact_result.scalars().all())
    if exact_accounts:
        exact_accounts.sort(key=lambda account: (account.nombre or "").lower())
        if limit:
            exact_accounts = exact_accounts[:limit]
        return [(account, 1.0) for account in exact_accounts]

    proveedores_result = await session.execute(
        select(ProveedorCliente).where(
            and_(
                ProveedorCliente.activo == True,
                ProveedorCliente.tipo != "empleado",
                or_(
                    ProveedorCliente.banco.isnot(None),
                    ProveedorCliente.cuenta_clabe.isnot(None),
                    ProveedorCliente.cuenta_bancaria.isnot(None),
                ),
            )
        )
    )
    proveedores = proveedores_result.scalars().all()

    scored = []
    for proveedor in proveedores:
        score = _empleado_proveedor_name_similarity(empleado_nombre, proveedor.nombre)
        if score >= threshold:
            scored.append((proveedor, score))

    scored.sort(key=lambda item: (-item[1], (item[0].nombre or "").lower()))
    if limit and len(scored) > limit:
        scored = scored[:limit]
    return scored


async def _html_empleado_bank_account_options(
    session: AsyncSession,
    empleado: Empleado,
    *,
    selected_id: Optional[str] = None,
) -> str:
    """Build <option> list for employee-matched bank accounts (solicitud personal)."""
    matches = await _get_matching_bank_accounts_for_empleado(
        session=session, empleado=empleado
    )
    selected = (selected_id or "").strip()
    options = (
        '<option value="" disabled'
        + (' selected' if not selected else '')
        + ' data-is-placeholder="true">— Seleccione cuenta bancaria —</option>'
    )
    for proveedor, _similarity in matches:
        nombre_escaped = escape(proveedor.nombre or "")
        banco_escaped = escape((proveedor.banco or "").strip())
        cuenta_escaped = escape((proveedor.cuenta_bancaria or "").strip())
        clabe_escaped = escape((proveedor.cuenta_clabe or "").strip())
        raw_account = (proveedor.cuenta_bancaria or "") or (proveedor.cuenta_clabe or "")
        last4 = raw_account[-4:] if raw_account and len(raw_account) >= 4 else ""
        u4_escaped = escape(last4) if last4 else ""
        label_parts = [nombre_escaped]
        if banco_escaped:
            label_parts.append(f"— {banco_escaped}")
        if last4:
            label_parts.append(f"(…{last4})")
        label = " ".join(label_parts)
        is_selected = selected and str(proveedor.id) == selected
        options += (
            f'<option value="{proveedor.id}" data-banco="{banco_escaped}" '
            f'data-cuenta="{cuenta_escaped}" data-cuenta-clabe="{clabe_escaped}" '
            f'data-ultimos4="{u4_escaped}"'
            f'{" selected" if is_selected else ""}>{label}</option>'
        )
    return options


