def _normalize_employee_identity_text(value: Any) -> str:
    text = unicodedata.normalize("NFKD", str(value or ""))
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    text = text.lower()
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return " ".join(text.split())


def _third_party_requester_name_matches(nombre: str) -> bool:
    if not nombre:
        return False
    normalized = _normalize_employee_identity_text(nombre)
    for allowed_raw in _THIRD_PARTY_EMPLOYEE_REQUESTER_NAMES:
        allowed = _normalize_employee_identity_text(allowed_raw)
        if normalized == allowed:
            return True
        if normalized.startswith(f"{allowed} "):
            return True
        if len(normalized.split()) >= 3 and allowed.startswith(f"{normalized} "):
            return True
    return False


def _is_company_amex_allowed_beneficiary(empleado: Optional[Empleado]) -> bool:
    if not empleado:
        return False
    normalized = _normalize_employee_identity_text(getattr(empleado, "nombre", ""))
    if not normalized:
        return False
    return normalized in {
        _normalize_employee_identity_text(name)
        for name in _COMPANY_AMEX_ALLOWED_BENEFICIARY_NAMES
    }


def _cuenta_allows_company_amex(cuenta: CuentaDeGastos) -> bool:
    beneficiary = getattr(cuenta, "beneficiario_empleado", None) or getattr(cuenta, "empleado", None)
    return _is_company_amex_allowed_beneficiary(beneficiary)


def _has_explicit_third_party_employee_request_permission(empleado: Empleado) -> bool:
    """Check assigned profile tokens without role/superadmin escalation."""

    permissions = {
        str(token or "").strip().lower()
        for token in (getattr(empleado, "permissions", set()) or set())
        if str(token or "").strip()
    }
    if "*" in permissions:
        return True
    return any(
        permission in permissions
        for permission in _THIRD_PARTY_EMPLOYEE_REQUESTER_PERMISSIONS
    )


def _can_request_for_other_employee(empleado: Empleado) -> bool:
    empleado_id = str(getattr(empleado, "id", "") or "")
    correo = (getattr(empleado, "correo", "") or "").strip().lower()
    nombre = _normalize_employee_identity_text(getattr(empleado, "nombre", ""))
    return bool(
        empleado_id in _THIRD_PARTY_EMPLOYEE_REQUESTER_IDS
        or correo in _THIRD_PARTY_EMPLOYEE_REQUESTER_EMAILS
        or _third_party_requester_name_matches(nombre)
        or _has_explicit_third_party_employee_request_permission(empleado)
    )


def _beneficiary_selection_allowed(
    requester: Empleado, beneficiary: Empleado
) -> bool:
    return (
        getattr(requester, "id", None) == getattr(beneficiary, "id", None)
        or _can_request_for_other_employee(requester)
    )


