async def _resolve_petty_cash_benjamin_employee(
    session: AsyncSession,
) -> Optional[Empleado]:
    r = await session.execute(
        select(Empleado).where(Empleado.activo.is_(True)).order_by(Empleado.nombre.asc())
    )
    for empleado in r.scalars().all():
        normalized = _normalize_employee_identity_text(getattr(empleado, "nombre", ""))
        if normalized in PETTY_CASH_BENJAMIN_NAMES:
            return empleado
    return None


def _petty_cash_beneficiary_control_html(
    *,
    requester: Empleado,
    selected_type: Optional[str],
    benjamin: Optional[Empleado],
) -> str:
    if not _can_request_for_other_employee(requester):
        return ""
    selected_type = _normalize_beneficiario_alterno_tipo(selected_type)
    benjamin_label = (
        (benjamin.nombre or benjamin.correo or str(benjamin.id))
        if benjamin is not None
        else "BENJAMIN JIMENEZ VIGUERAS"
    )
    boxes = []
    for type_key, config in PETTY_CASH_BENEFICIARY_TYPES.items():
        checked = " checked" if selected_type == type_key else ""
        benjamin_id = str(benjamin.id) if benjamin is not None else ""
        boxes.append(
            f'<label style="display:flex;align-items:flex-start;gap:8px;margin:0;font-weight:800;">'
            f'<input type="checkbox" class="petty-cash-toggle beneficiary-mode-toggle" '
            f'name="beneficiario_alterno_tipo" value="{escape(type_key)}" '
            f'data-beneficiary-mode="petty-cash" data-benjamin-id="{benjamin_id}"{checked}> '
            f'<span>{escape(config["label"])}<br>'
            f'<small style="font-weight:500;color:#64748b;">{escape(config["description"])}</small></span>'
            f'</label>'
        )
    return (
        '<div class="petty-cash-beneficiary-control" '
        'style="border:1px solid #fed7aa;background:#fff7ed;border-radius:12px;'
        'padding:12px 14px;margin:0 0 10px 0;display:grid;gap:10px;">'
        '<strong>Es para caja chica</strong>'
        + "".join(boxes)
        + f'<small>Las solicitudes vinculadas quedan a nombre de {escape(benjamin_label)}; '
        'la cuenta contable de caja chica se determina por el tipo seleccionado.</small>'
        '</div>'
    )


def _beneficiary_employee_control_html(
    *,
    requester: Empleado,
    beneficiary: Empleado,
    options_html: str,
    select_id: str,
    help_text: str,
    title: str = "Empleado beneficiario",
    use_activation: bool = False,
) -> str:
    """Render an explicit employee selector only for authorized requesters."""
    beneficiary_name = escape(
        beneficiary.nombre or beneficiary.correo or str(beneficiary.id)
    )
    control_style = (
        "border:1px solid #c7d2fe;background:#eef2ff;border-radius:12px;"
        "padding:12px 14px;margin:0 0 10px 0;display:grid;gap:8px;"
    )
    badge_style = (
        "display:inline-block;background:#1d4ed8;color:white;border-radius:999px;"
        "padding:2px 8px;font-size:11px;font-weight:800;letter-spacing:.02em;"
    )
    title_safe = escape(title)
    requester_id = getattr(requester, "id", None)
    beneficiary_id = getattr(beneficiary, "id", None)
    activation_checked = bool(use_activation and requester_id and beneficiary_id and requester_id != beneficiary_id)
    activation_checked_attr = " checked" if activation_checked else ""
    activation_html = (
        f'<label style="display:flex;align-items:center;gap:8px;margin:0;font-weight:800;">'
        f'<input type="checkbox" id="{select_id}_enabled" class="beneficiary-mode-toggle" data-beneficiary-mode="employee"{activation_checked_attr}> '
        f'{title_safe}</label>'
        if use_activation
        else f'<div><span style="{badge_style}">Paso 1</span> <strong>{title_safe}</strong></div>'
    )
    select_disabled = " disabled" if use_activation and not activation_checked else ""
    default_beneficiary_attr = f' data-default-beneficiary-id="{escape(str(requester.id))}"' if use_activation else ""
    if _can_request_for_other_employee(requester):
        return (
            f'<div class="employee-beneficiary-control" style="{control_style}">'
            f'{activation_html}'
            f'<label for="{select_id}" style="display:block;font-weight:700;">'
            'Elige quien recibira el recurso</label>'
            f'<select name="beneficiario_empleado_id" id="{select_id}" required{select_disabled}{default_beneficiary_attr} '
            f'style="margin-bottom:2px;">{options_html}</select>'
            f'<small>{escape(help_text)}</small>'
            '</div>'
        )
    locked_title = "Beneficiario del informe" if use_activation else title_safe
    locked_heading = (
        f'<div><strong>{locked_title}</strong></div>'
        if use_activation
        else f'<div><span style="{badge_style}">Beneficiario</span> <strong>{locked_title}</strong></div>'
    )
    return (
        f'<div class="employee-beneficiary-control locked" style="{control_style}">'
        f'<input type="hidden" name="beneficiario_empleado_id" value="{beneficiary.id}">'
        f'{locked_heading}'
        f'<span style="display:block;font-weight:800;">{beneficiary_name}</span>'
        '<small>Este usuario solamente puede solicitar para si mismo.</small>'
        '</div>'
    )

def _can_cancel_empty_informe_draft(
    actor: Empleado, cuenta: CuentaDeGastos
) -> bool:
    """Only the requester/owner, finance, or superadmin can cancel an empty draft."""
    role = (getattr(actor, "rol", None) or "").strip().lower()
    return bool(
        getattr(cuenta, "empleado_id", None) == getattr(actor, "id", None)
        or role in {"finanzas", "superadmin", "super_admin"}
    )


def _empty_informe_cancel_error(
    *,
    cuenta_estado: str,
    informe_estado: str,
    expense_count: int,
    solicitud_count: int,
    settlement_count: int,
    attachment_count: int,
) -> Optional[str]:
    if cuenta_estado != "abierta" or informe_estado != "borrador":
        return "Solo puede cancelarse un informe abierto que siga en borrador."
    if expense_count:
        return "El informe tiene gastos vinculados y no puede cancelarse como vacío."
    if solicitud_count:
        return "El informe tiene solicitudes vinculadas y no puede cancelarse como vacío."
    if settlement_count:
        return "El informe tiene liquidaciones vinculadas y no puede cancelarse como vacío."
    if attachment_count:
        return "El informe tiene archivos vinculados y no puede cancelarse como vacío."
    return None

