@router.get("/api/empleados/{beneficiario_id}/cuentas-bancarias")
async def employee_bank_accounts_for_beneficiary(
    beneficiario_id: UUIDType,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
) -> JSONResponse:
    result = await session.execute(
        select(Empleado).where(
            Empleado.id == beneficiario_id,
            Empleado.activo == True,
        )
    )
    beneficiario = result.scalar_one_or_none()
    if beneficiario is None:
        raise HTTPException(status_code=404, detail="Beneficiario no encontrado o inactivo")
    if not _beneficiary_selection_allowed(current_empleado, beneficiario):
        raise HTTPException(
            status_code=403,
            detail="No tienes permiso para solicitar a nombre de otro empleado",
        )
    matches = await _get_matching_bank_accounts_for_empleado(session, beneficiario)
    return JSONResponse(
        content={
            "beneficiario": {
                "id": str(beneficiario.id),
                "nombre": beneficiario.nombre or "",
            },
            "cuentas": [
                {
                    "id": str(proveedor.id),
                    "nombre": proveedor.nombre or "",
                    "banco": proveedor.banco or "",
                    "cuenta": proveedor.cuenta_bancaria or "",
                    "cuenta_clabe": proveedor.cuenta_clabe or "",
                }
                for proveedor, _score in matches
            ],
        }
    )


def _solicitar_anticipo_form_url(
    *,
    error_msg: Optional[str] = None,
    torneo_id: str = "",
    fase: str = "",
    concepto_pago: str = "",
    monto_solicitado: str = "",
    proveedor_cliente_id: str = "",
    currency: str = "",
    edicion: str = "",
    budget_concept_id: str = "",
    beneficiario_empleado_id: str = "",
    beneficiario_operador_id: str = "",
) -> str:
    """Build redirect URL back to Solicitar Anticipo with optional preserved fields."""
    url = "/gastos-terceros/solicitar-anticipo"
    if error_msg:
        url = _append_error_params(url, error_msg=error_msg)
    extra: List[str] = []
    if torneo_id:
        extra.append(f"torneo_id={quote(str(torneo_id))}")
    if fase:
        extra.append(f"fase={quote(fase)}")
    if concepto_pago:
        extra.append(f"concepto_pago={quote(concepto_pago)}")
    if monto_solicitado:
        extra.append(f"monto_solicitado={quote(monto_solicitado)}")
    if proveedor_cliente_id:
        extra.append(f"proveedor_cliente_id={quote(str(proveedor_cliente_id))}")
    if currency:
        extra.append(f"currency={quote(currency)}")
    if edicion:
        extra.append(f"edicion={quote(edicion)}")
    if budget_concept_id:
        extra.append(f"budget_concept_id={quote(budget_concept_id)}")
    if beneficiario_empleado_id:
        extra.append(
            f"beneficiario_empleado_id={quote(str(beneficiario_empleado_id))}"
        )
    if beneficiario_operador_id:
        extra.append(
            f"beneficiario_operador_id={quote(str(beneficiario_operador_id))}"
        )
    if not extra:
        return url
    joiner = "&" if "?" in url else "?"
    return url + joiner + "&".join(extra)


def resolve_project_name(proyecto: str, tournament_map: dict) -> str:
    """
    Resolve project name from UUID or return as-is.

    If proyecto is a valid UUID and exists in tournament_map, return the tournament name.
    Otherwise, return the proyecto value as-is.

    Args:
        proyecto: The project value (could be UUID or name string)
        tournament_map: Dictionary mapping tournament UUID strings to tournament names

    Returns:
        The resolved project name
    """
    if not proyecto:
        return "-"

    # Check if it's a UUID and we have a mapping
    if is_valid_uuid(proyecto):
        tournament_name = tournament_map.get(proyecto.lower())
        if tournament_name:
            return tournament_name

    return proyecto


def documento_project_name(documento: Documento, torneo: Optional[Tournament]) -> str:
    manual_project = (getattr(documento, "proyecto_otro", None) or "").strip()
    if manual_project:
        return manual_project
    if torneo and torneo.name:
        return torneo.name
    cuenta = getattr(documento, "cuenta_gastos", None)
    cuenta_torneo = getattr(cuenta, "torneo", None)
    if cuenta_torneo and getattr(cuenta_torneo, "name", None):
        return cuenta_torneo.name
    return ""


async def _load_related_document_project_context(
    session: AsyncSession, documento: Documento
) -> tuple[Optional[Tournament], str]:
    """Fallback project/fase from sibling documents that share referencia_operaciones."""
    ref_ops = str(getattr(documento, "referencia_operaciones", None) or "").strip()
    if not ref_ops:
        return None, ""
    result = await session.execute(
        select(Documento)
        .options(
            selectinload(Documento.torneo),
            selectinload(Documento.cuenta_gastos)
                .undefer(CuentaDeGastos.torneo_id)
                .undefer(CuentaDeGastos.fase)
                .selectinload(CuentaDeGastos.torneo),
            undefer(Documento.fase),
        )
        .outerjoin(CuentaDeGastos, Documento.cuenta_gastos_id == CuentaDeGastos.id)
        .where(
            Documento.id != documento.id,
            Documento.referencia_operaciones == ref_ops,
            or_(Documento.torneo_id.isnot(None), CuentaDeGastos.torneo_id.isnot(None)),
        )
        .order_by(Documento.creado_en.asc())
        .limit(1)
    )
    sibling = result.scalar_one_or_none()
    if sibling is None:
        return None, ""
    sibling_cuenta = getattr(sibling, "cuenta_gastos", None)
    torneo = getattr(sibling, "torneo", None) or getattr(sibling_cuenta, "torneo", None)
    fase = str(getattr(sibling, "fase", None) or getattr(sibling_cuenta, "fase", None) or "").strip()
    return torneo, fase


def _solicitud_header_date(documento: Documento):
    """Mirror Excel E4 date source, normalized to a CDMX calendar date."""
    if documento.cuenta_gastos_id and documento.creado_en:
        enviado = to_mexico_city_date(documento.creado_en)
    elif documento.enviado_en:
        enviado = to_mexico_city_date(documento.enviado_en)
    else:
        enviado = None

    if enviado:
        return enviado

    return to_mexico_city_date(
        documento.fecha_inicio or documento.fecha_fin or documento.creado_en
    )


async def _resolve_solicitud_approval_display_name(
    session: AsyncSession,
    aprobaciones: List[Aprobacion],
) -> str:
    """Return the real approval actor for the transfer request signature."""
    latest_approval = next(
        (
            aprobacion
            for aprobacion in aprobaciones
            if (aprobacion.accion or "").strip().lower() == "aprobar"
        ),
        None,
    )
    if latest_approval is None or not latest_approval.aprobador_id:
        return ""

    loaded_approver = getattr(latest_approval, "aprobador", None)
    if loaded_approver and getattr(loaded_approver, "nombre", None):
        return loaded_approver.nombre or ""

    aprobador_result = await session.execute(
        select(Empleado).where(Empleado.id == latest_approval.aprobador_id)
    )
    aprobador = aprobador_result.scalar_one_or_none()
    return aprobador.nombre if aprobador and aprobador.nombre else ""


def documento_fase_display(documento: Documento) -> str:
    try:
        raw = getattr(documento, "fase", None)
        if raw is None or not str(raw).strip():
            cuenta = getattr(documento, "cuenta_gastos", None)
            raw = getattr(cuenta, "fase", None)
        return (str(raw).strip() if raw is not None else "") or ""
    except (ProgrammingError, OperationalError, Exception):
        return ""


def _is_solicitud_terceros(documento: Documento) -> bool:
    return (
        documento.tipo == "SOLICITUD"
        and documento.proveedor_cliente_id is not None
        and getattr(documento, "cuenta_gastos_id", None) is None
    )


def _budget_concept_assigned(documento: Documento) -> bool:
    return bool(getattr(documento, "budget_concept_id", None))


def _is_pre_budget_edit_window(documento: Documento) -> bool:
    """User-editable window before Control Presupuestal assigns a budget concept."""
    estado = (getattr(documento, "estado", None) or "").strip().lower()
    if estado == "borrador":
        return not _budget_concept_assigned(documento)
    if estado == "rechazado":
        return True
    return estado == "control_presupuestal" and not _budget_concept_assigned(documento)


def _can_edit_solicitud_terceros(
    documento: Documento,
    empleado: Empleado,
    *,
    solicitud_cancelada: bool = False,
) -> bool:
    return (
        _is_solicitud_terceros(documento)
        and _is_pre_budget_edit_window(documento)
        and documento.empleado_id == empleado.id
        and not solicitud_cancelada
    )


def _can_add_solicitud_adjuntos(
    documento: Documento,
    empleado: Empleado,
    *,
    solicitud_cancelada: bool = False,
) -> bool:
    if not _is_solicitud_terceros(documento) or solicitud_cancelada:
        return False
    rol = (empleado.rol or "").strip().lower()
    finance_roles = {"finanzas", "admin", "superadmin", "super_admin"}
    allowed_states = {"borrador", "aprobado", "pagado"}
    if rol in finance_roles:
        return documento.estado in allowed_states | {"enviado"}
    if documento.empleado_id != empleado.id:
        return False
    return documento.estado in allowed_states


def _can_remove_solicitud_adjunto(
    documento: Documento,
    empleado: Empleado,
    categoria: str,
    *,
    solicitud_cancelada: bool = False,
) -> bool:
    categoria_norm = (categoria or "supporting").strip().lower()
    if categoria_norm == "comprobante_pago":
        return _can_finance_add_comprobante_pago(
            documento,
            empleado,
            solicitud_cancelada=solicitud_cancelada,
        )
    return _can_add_solicitud_adjuntos(
        documento,
        empleado,
        solicitud_cancelada=solicitud_cancelada,
    )


def _removable_solicitud_adjunto_ids(
    documento: Documento,
    empleado: Empleado,
    adjuntos: list,
    *,
    solicitud_cancelada: bool = False,
) -> set[UUIDType]:
    removable: set[UUIDType] = set()
    for meta in adjuntos:
        adjunto_id = _adjunto_meta_id(meta)
        if adjunto_id is None:
            continue
        categoria = getattr(meta, "categoria", None) or "supporting"
        if _can_remove_solicitud_adjunto(
            documento,
            empleado,
            categoria,
            solicitud_cancelada=solicitud_cancelada,
        ):
            removable.add(adjunto_id)
    return removable


def _can_finance_add_comprobante_pago(
    documento: Documento,
    empleado: Empleado,
    *,
    solicitud_cancelada: bool = False,
) -> bool:
    """Accounting payment closers attach proof only after payment-run cutoff."""
    if solicitud_cancelada or not _is_solicitud_terceros(documento):
        return False
    if not can_confirm_payment_run_payment(empleado):
        return False
    return documento.estado == "en_proceso_pago"


def _nueva_solicitud_terceros_form_url(
    *,
    error_msg: Optional[str] = None,
    error: Optional[str] = None,
    torneo_id: str = "",
    fase: str = "",
    budget_concept_id: str = "",
) -> str:
    url = _append_error_params(
        "/documentos/nueva-solicitud-terceros",
        error=error,
        error_msg=error_msg,
    )
    extra: List[str] = []
    if torneo_id:
        extra.append(f"torneo_id={quote(str(torneo_id))}")
    if fase:
        extra.append(f"fase={quote(fase)}")
    if budget_concept_id:
        extra.append(f"budget_concept_id={quote(str(budget_concept_id))}")
    if not extra:
        return url
    joiner = "&" if "?" in url else "?"
    return url + joiner + "&".join(extra)


async def _validate_solicitud_terceros_fase(
    session: AsyncSession,
    *,
    empleado: Empleado,
    torneo_id_raw: str,
    fase_raw: str,
) -> Tuple[Optional[str], Optional[str]]:
    """Validate optional fase for standalone solicitud a terceros."""
    torneo_raw = (torneo_id_raw or "").strip()
    if torneo_raw == "__otro__" or not torneo_raw:
        if not (fase_raw or "").strip():
            return None, None
        return (
            "Fase/Subproyecto no aplica cuando el proyecto es manual.",
            None,
        )
    try:
        torneo_uuid = UUIDType(torneo_raw)
    except (ValueError, TypeError):
        return "El proyecto seleccionado no es válido.", None

    t_row = await session.get(Tournament, torneo_uuid)
    if not t_row:
        return "El proyecto indicado no existe.", None
    if not bool(getattr(t_row, "active", True)):
        return "Debe seleccionar un proyecto activo.", None

    vis_err = visibility_validation_error(t_row, empleado)
    if vis_err:
        return vis_err, None

    raw_etapas = getattr(t_row, "etapas", None)
    allowed: List[str] = []
    if raw_etapas and isinstance(raw_etapas, list):
        allowed = [str(x).strip() for x in raw_etapas if x is not None and str(x).strip()]
    if not allowed:
        if not (fase_raw or "").strip():
            return None, None
        return (
            "Este torneo/proyecto no tiene fases configuradas; deje Fase/Subproyecto vacío.",
            None,
        )
    fase_st = (fase_raw or "").strip()
    if not fase_st:
        return "Debe seleccionar una Fase/Subproyecto para el proyecto.", None
    if fase_st not in allowed:
        return (
            "La fase no corresponde al torneo/proyecto seleccionado.",
            None,
        )
    return None, fase_st


def _post_action_cta_html(
    *,
    primary_href: Optional[str],
    primary_label: Optional[str],
    home_href: str = "/panel",
    home_label: str = "Volver al inicio",
) -> str:
    actions: List[str] = []
    if primary_href and primary_label:
        actions.append(
            f'<a href="{escape(primary_href)}" class="button primary">{escape(primary_label)}</a>'
        )
    actions.append(
        f'<a href="{escape(home_href)}" class="button secondary">{escape(home_label)}</a>'
    )
    return (
        '<div class="inline-actions" style="margin-top:12px;">'
        + "".join(actions)
        + "</div>"
    )


def _document_primary_action(documento: Documento, *, approval_mode: bool = False) -> Tuple[str, str]:
    if approval_mode:
        return "/documentos/pendientes", "Realizar otra aprobación"
    if documento.tipo == "SOLICITUD":
        if getattr(documento, "cuenta_gastos_id", None):
            return (
                f"/informes-de-gastos/{documento.cuenta_gastos_id}/nueva-solicitud",
                "Realizar otra solicitud",
            )
        return "/documentos/nueva-solicitud-terceros", "Realizar otra solicitud"
    if documento.tipo == "INFORME":
        if documento.cuenta_gastos_id:
            return (
                f"/gastos/nuevo?cuenta_gastos_id={documento.cuenta_gastos_id}",
                "Registrar otro gasto",
            )
        return "/informes-de-gastos/crear", "Crear otro informe"
    return "/gastos/nuevo", "Registrar otro gasto"


def _document_success_actions_html(
    documento: Documento,
    *,
    approval_mode: bool = False,
) -> str:
    primary_href, primary_label = _document_primary_action(
        documento,
        approval_mode=approval_mode,
    )
    return _post_action_cta_html(
        primary_href=primary_href,
        primary_label=primary_label,
    )


def _cuenta_success_actions_html(
    *,
    cuenta_id: UUIDType,
    cuenta_estado: str,
    success_code: Optional[str],
) -> str:
    success_code_normalized = (success_code or "").strip().lower()
    if success_code_normalized == "creada":
        return _post_action_cta_html(
            primary_href="/informes-de-gastos/crear",
            primary_label="Crear otro informe",
        )
    if success_code_normalized == "solicitud_creada" and cuenta_estado == "abierta":
        return _post_action_cta_html(
            primary_href=f"/informes-de-gastos/{cuenta_id}/nueva-solicitud",
            primary_label="Crear otra solicitud",
        )
    if success_code_normalized in {"gastos_adjuntados", "editada"} and cuenta_estado == "abierta":
        return _post_action_cta_html(
            primary_href=f"/gastos/nuevo?cuenta_gastos_id={cuenta_id}",
            primary_label="Registrar otro gasto",
        )
    if success_code_normalized == "saldada":
        return _post_action_cta_html(
            primary_href="/informes-de-gastos",
            primary_label="Abrir otro informe",
        )
    if success_code_normalized == "cerrada":
        return _post_action_cta_html(
            primary_href=f"/informes-de-gastos/{cuenta_id}/exportar-informe.xlsx",
            primary_label="Descargar informe de gastos",
            home_href="/informes-de-gastos",
            home_label="Abrir otro informe",
        )
    return _post_action_cta_html(
        primary_href=f"/informes-de-gastos/{cuenta_id}",
        primary_label="Volver al informe",
    )


def extract_uuid_from_qr_or_url(text: str) -> Optional[str]:
    """
    Extract CFDI UUID from QR code text or URL.

    Mexico CFDI QR codes typically contain uuid=... parameter.
    Also handles direct UUID strings and various URL formats.

    Returns normalized UUID (uppercase, canonical) or None if not found.
    """
    if not text or not text.strip():
        return None

    text = text.strip()

    # Try to extract UUID from URL parameters (uuid=...)
    try:
        # Parse as URL
        parsed = urlparse(text)
        params = parse_qs(parsed.query)

        # Check for uuid parameter (case-insensitive)
        for key in params:
            if key.lower() == 'uuid':
                uuid_val = params[key][0] if params[key] else None
                if uuid_val:
                    # Validate and normalize UUID
                    try:
                        uuid_obj = UUIDType(uuid_val)
                        return str(uuid_obj).upper()
                    except ValueError:
                        pass
    except (AttributeError, TypeError, ValueError):
        pass

    # Try to find UUID pattern in text (standard UUID format: 8-4-4-4-12 hex digits)
    uuid_pattern = r'[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}'
    matches = re.findall(uuid_pattern, text)
    if matches:
        try:
            uuid_obj = UUIDType(matches[0])
            return str(uuid_obj).upper()
        except ValueError:
            pass

    # Try to parse as direct UUID
    try:
        uuid_obj = UUIDType(text)
        return str(uuid_obj).upper()
    except ValueError:
        pass

    return None


def format_value(value) -> str:
    """Format a value for display."""
    if value is None:
        return "-"
    if isinstance(value, datetime):
        return value.strftime("%Y-%m-%d")
    return str(value)


def format_currency(value, currency: str = "MXN") -> str:
    """Format a numeric value as currency."""
    code = normalize_currency(currency)
    symbol = {"MXN": "$", "USD": "US$", "EUR": "€"}.get(code, f"{code} ")
    if value is None:
        return f"{symbol}0.00"
    try:
        amount = Decimal(str(value)).quantize(
            Decimal("0.01"), rounding=ROUND_HALF_UP
        )
        return f"{symbol}{amount:,.2f}"
    except (InvalidOperation, ValueError, TypeError):
        return str(value)


def _format_authorization_money_value(value: Any) -> str:
    """Format advisory authorization amounts without leaking binary float noise."""
    if value is None:
        return "--"
    if isinstance(value, str) and not value.strip():
        return "--"
    try:
        return format_currency(value, "MXN")
    except Exception:
        return str(value)


