@router.post("/documentos/{documento_id}/registrar-anticipo")
async def registrar_anticipo(
    documento_id: UUIDType,
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
    monto: str = Form(...),
    moneda: str = Form(...),
    fecha_entrega: str = Form(...),
    estado: str = Form("pendiente"),
) -> RedirectResponse:
    """
    Register an anticipo (advance) for a SOLICITUD document.
    Only allowed for tipo = 'SOLICITUD' and estado = 'aprobado'.
    """
    # Load documento
    doc_result = await session.execute(
        select(Documento).where(Documento.id == documento_id)
    )
    documento = doc_result.scalar_one_or_none()

    if not documento:
        raise HTTPException(status_code=404, detail="Documento not found")

    # Verify access: owner OR finanzas/admin (coordinador same as empleado: own only)
    if documento.empleado_id != current_empleado.id and current_empleado.rol not in ['finanzas', 'admin', 'superadmin', 'super_admin']:
        raise HTTPException(status_code=403, detail="Acceso denegado")

    # Validate tipo - only SOLICITUD allowed
    if documento.tipo != 'SOLICITUD':
        return RedirectResponse(
            url=_append_error_params(
                f"/documentos/{documento_id}",
                error="invalid_tipo",
                error_msg="Solo se pueden registrar anticipos en documentos de tipo SOLICITUD.",
            ),
            status_code=303
        )

    # Validate estado - must be aprobado
    if documento.estado != 'aprobado':
        return RedirectResponse(
            url=_append_error_params(
                f"/documentos/{documento_id}",
                error="invalid_estado",
                error_msg="El documento debe estar aprobado antes de registrar un anticipo.",
            ),
            status_code=303
        )

    # Parse monto
    try:
        monto_decimal = float(monto)
        if monto_decimal <= 0:
            return RedirectResponse(
                url=_append_error_params(
                    f"/documentos/{documento_id}",
                    error="invalid_monto",
                    error_msg="El monto debe ser mayor a cero.",
                ),
                status_code=303
            )
    except ValueError:
        return RedirectResponse(
            url=_append_error_params(
                f"/documentos/{documento_id}",
                error="invalid_monto",
                error_msg="El monto ingresado no es válido.",
            ),
            status_code=303
        )

    # Parse fecha_entrega
    try:
        fecha_entrega_dt = datetime.strptime(fecha_entrega, "%Y-%m-%d")
    except ValueError:
        return RedirectResponse(
            url=_append_error_params(
                f"/documentos/{documento_id}",
                error="invalid_fecha",
                error_msg="La fecha de entrega no es válida.",
            ),
            status_code=303
        )

    # Amount sanity check: if monto_total is set, check that total anticipos + nuevo monto <= monto_total
    if documento.monto_total is not None and documento.monto_total > 0:
        # Calculate total existing anticipos
        total_anticipos_result = await session.execute(
            select(func.coalesce(func.sum(Anticipo.monto), 0))
            .where(Anticipo.documento_id == documento_id)
        )
        total_anticipos_existentes = float(total_anticipos_result.scalar_one() or 0)

        if total_anticipos_existentes + monto_decimal > float(documento.monto_total):
            return RedirectResponse(
                url=_append_error_params(
                    f"/documentos/{documento_id}",
                    error="exceso_monto",
                    error_msg=(
                        f"El total de anticipos ({format_currency(total_anticipos_existentes + monto_decimal)}) "
                        f"excede el monto total del documento ({format_currency(documento.monto_total)})."
                    ),
                ),
                status_code=303
            )

    # Create anticipo
    anticipo = Anticipo(
        empleado_id=documento.empleado_id,
        documento_id=documento_id,
        monto=monto_decimal,
        moneda=moneda,
        fecha_entrega=fecha_entrega_dt,
        estado=estado,
        creado_en=datetime.utcnow()
    )
    session.add(anticipo)
    await session.flush()
    anticipo_employee = await session.get(Empleado, documento.empleado_id)
    if anticipo_employee is not None:
        await ensure_debtor_payment_posting_for_document(
            session,
            documento=documento,
            empleado=anticipo_employee,
            fecha_pago=fecha_entrega_dt,
            require_employee_beneficiary=False,
        )

    await session.commit()

    logger.info(f"Anticipo registrado para documento {documento_id}: {monto} {moneda}")

    return RedirectResponse(
        url=_append_success_params(
            f"/documentos/{documento_id}",
            success_msg="Anticipo registrado exitosamente",
        ),
        status_code=303
    )


@router.post("/documentos/{documento_id}/registrar-pago")
async def registrar_pago(
    documento_id: UUIDType,
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
    next: Optional[str] = Form(None),
) -> RedirectResponse:
    """Legacy endpoint: payment confirmation now requires proof upload."""
    redirect_url = determine_redirect_url(next, documento_id, default_to_detail=True)
    return RedirectResponse(
        url=_append_error_params(
            redirect_url,
            error="payment_proof_required",
            error_msg=(
                "El pago se confirma adjuntando comprobante desde Programación de Pagos."
            ),
        ),
        status_code=303,
    )


@router.post("/documentos/{documento_id}/registrar-reembolso")
async def registrar_reembolso(
    documento_id: UUIDType,
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
    monto: str = Form(...),
    moneda: str = Form(...),
    metodo_pago: Optional[str] = Form(None),
    fecha_pago: Optional[str] = Form(None),
    estado: str = Form("pagado"),
) -> RedirectResponse:
    """
    Legacy endpoint retained only for INFORMEs NOT linked to a Cuenta de Gastos.

    v1.0.24 moved the reimbursement UX to `/informes-de-gastos/{cuenta_id}/saldar`.
    Any INFORME with a `cuenta_gastos_id` is redirected there; this path exists purely for
    backfill tooling on pre-cuenta documents and is not surfaced in the UI.
    """
    documento_row = await session.execute(
        select(Documento).where(Documento.id == documento_id)
    )
    documento = documento_row.scalar_one_or_none()
    if documento is None:
        raise HTTPException(status_code=404, detail="Documento no encontrado")

    if documento.cuenta_gastos_id:
        return RedirectResponse(
            url=(
                f"/informes-de-gastos/{documento.cuenta_gastos_id}/saldar"
                "?error_msg="
                + quote(
                    "Los reembolsos ahora se registran desde la cuenta de gastos."
                )
            ),
            status_code=303,
        )

    try:
        await register_document_reembolso(
            session,
            documento_id=documento_id,
            actor_id=current_empleado.id,
            monto=monto,
            moneda=moneda,
            metodo_pago=metodo_pago,
            fecha_pago=fecha_pago,
            estado=estado,
        )
    except DocumentoPaymentPermissionError as exc:
        raise HTTPException(status_code=403, detail=exc.message)
    except DocumentoPaymentValidationError as exc:
        if exc.code == "documento_not_found":
            raise HTTPException(status_code=404, detail=exc.message)
        return RedirectResponse(
            url=_append_error_params(
                f"/documentos/{documento_id}",
                error=exc.code,
                error_msg=exc.message,
            ),
            status_code=303,
        )
    except Exception:
        await session.rollback()
        logger.exception(
            "Unexpected error registering documento reimbursement",
            extra={
                "documento_id": str(documento_id),
                "actor_id": str(current_empleado.id),
            },
        )
        return RedirectResponse(
            url=_append_error_params(
                f"/documentos/{documento_id}",
                error="unexpected_documento_reembolso",
                error_msg=(
                    "Ocurrió un error al registrar la operación. "
                    "Intente nuevamente."
                ),
            ),
            status_code=303,
        )

    logger.info(f"Reembolso registrado para documento {documento_id}: {monto} {moneda}")

    return RedirectResponse(
        url=_append_success_params(
            f"/documentos/{documento_id}",
            success_msg="Reembolso registrado exitosamente",
        ),
        status_code=303
    )


async def _build_documento_coi_bundle(
    documento_id: UUIDType,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
) -> tuple[Documento, list[ExpenseReport], list[ExpenseCFDI]]:
    # Load documento
    doc_result = await session.execute(
        select(Documento).where(Documento.id == documento_id)
    )
    documento = doc_result.scalar_one_or_none()

    if not documento:
        raise HTTPException(status_code=404, detail="Documento not found")

    # Verify access: owner OR coordinador/finanzas/admin
    if documento.empleado_id != current_empleado.id and current_empleado.rol not in ['coordinador', 'finanzas', 'admin', 'superadmin', 'super_admin']:
        raise HTTPException(status_code=403, detail="Access denied")

    if documento.tipo == "INFORME" and documento.estado != "aprobado":
        raise HTTPException(
            status_code=409,
            detail="El documento INFORME debe estar aprobado antes de exportar la poliza COI.",
        )

    # Load related expenses (exclude cancelled).
    # For INFORME: include expenses linked via documento_id, informe_documento_id, or cuenta_gastos_id (same as detail page).
    if documento.tipo == 'INFORME':
        expense_conditions = [
            ExpenseReport.documento_id == documento_id,
            ExpenseReport.informe_documento_id == documento_id,
        ]
        if documento.cuenta_gastos_id:
            expense_conditions.append(ExpenseReport.cuenta_gastos_id == documento.cuenta_gastos_id)
        expenses_result = await session.execute(
            select(ExpenseReport)
            .options(selectinload(ExpenseReport.cuenta_contable))
            .options(selectinload(ExpenseReport.cfdi_report))
            .options(selectinload(ExpenseReport.contra_cuenta_contable))
            .options(selectinload(ExpenseReport.cuenta_iva))
            .where(
                and_(
                    or_(*expense_conditions),
                    ExpenseReport.estado_gasto != 'cancelado'
                )
            )
            .order_by(ExpenseReport.fecha.asc())
        )
    else:
        expenses_result = await session.execute(
            select(ExpenseReport)
            .options(selectinload(ExpenseReport.cuenta_contable))
            .options(selectinload(ExpenseReport.cfdi_report))
            .options(selectinload(ExpenseReport.contra_cuenta_contable))
            .options(selectinload(ExpenseReport.cuenta_iva))
            .where(
                and_(
                    ExpenseReport.documento_id == documento_id,
                    ExpenseReport.estado_gasto != 'cancelado'
                )
            )
            .order_by(ExpenseReport.fecha.asc())
        )
    expenses = expenses_result.scalars().all()

    if not expenses:
        raise HTTPException(
            status_code=400,
            detail="No hay gastos activos asociados para exportar.",
        )

    expense_cfdi_list: list[ExpenseCFDI] = []
    ready_expenses: list[ExpenseReport] = []
    for expense in expenses:
        ready, _ = await assess_expense_coi_cleanup_ready(session, expense)
        if not ready:
            continue
        try:
            expense_cfdi_list.append(
                await build_expense_cfdi_for_export(
                    session,
                    expense,
                    require_cleanup_ready=False,
                )
            )
            ready_expenses.append(expense)
        except ValueError as exc:
            logger.warning(
                "Skipping expense %s for documento COI export: %s",
                expense.id,
                exc,
            )

    if not ready_expenses:
        raise HTTPException(
            status_code=400,
            detail=(
                "Ningún gasto completó la limpieza contable (Listo COI). "
                "Guarde la limpieza en Centro de Limpieza Contable antes de exportar."
            ),
        )

    return documento, ready_expenses, expense_cfdi_list


async def _approved_informe_for_cuenta_or_redirect(
    cuenta_id: UUIDType,
    session: AsyncSession,
    current_empleado: Empleado,
    artifact_label: str = "COI",
) -> Union[Documento, RedirectResponse]:
    cuenta_result = await session.execute(
        select(CuentaDeGastos).where(CuentaDeGastos.id == cuenta_id)
    )
    cuenta = cuenta_result.scalar_one_or_none()
    if cuenta is None:
        raise HTTPException(status_code=404, detail="Informe de Gastos no encontrado")
    if not _can_access_reembolso_cuenta(cuenta, current_empleado):
        raise HTTPException(status_code=403, detail="Acceso denegado")

    informe_doc = await _informe_documento_for_cuenta(session, cuenta_id)
    if informe_doc is None:
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}",
                error="no_informe_doc",
                error_msg=f"Este informe no tiene documento INFORME vinculado para generar {artifact_label}.",
            ),
            status_code=303,
        )
    if informe_doc.estado != "aprobado":
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}",
                error="informe_not_approved",
                error_msg=f"La descarga {artifact_label} se habilita cuando el INFORME este aprobado.",
            ),
            status_code=303,
        )
    return informe_doc


