@router.post("/informes-de-gastos/{cuenta_id}/editar")
async def editar_cuenta_de_gastos_submit(
    cuenta_id: UUIDType,
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
) -> RedirectResponse:
    """Update Cuenta de Gastos classification (tipo, torneo, fase). Only when abierta."""
    from urllib.parse import quote
    form_data = await request.form()
    try:
        cuenta_result = await session.execute(
            select(CuentaDeGastos).where(CuentaDeGastos.id == cuenta_id)
        )
        cuenta = cuenta_result.scalar_one_or_none()
    except (ProgrammingError, OperationalError):
        return _schema_outdated_html_response()
    if not cuenta or (current_empleado.rol not in ("admin", "finanzas") and cuenta.empleado_id != current_empleado.id):
        raise HTTPException(status_code=404, detail="Informe de Gastos no encontrado")
    informe_doc = await _informe_documento_for_cuenta(session, cuenta_id)
    if not _can_edit_cuenta_before_budget_assignment(cuenta, informe_doc):
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}",
                error_msg="No se puede editar un informe después de que Control Presupuestal asignó concepto o entró a aprobaci?n.",
            ),
            status_code=303,
        )
    nombre_val = (form_data.get("nombre") or "").strip() or None
    tipo_cuenta_raw = form_data.get("tipo_cuenta") or "local"
    torneo_id_raw = form_data.get("torneo_id") or ""
    fase_raw = (form_data.get("fase") or "").strip()
    err, tipo_ok, torneo_id_uuid, fase_final = await _validate_cuenta_informe_proyecto_fields(
        session,
        empleado=current_empleado,
        tipo_cuenta_raw=tipo_cuenta_raw,
        torneo_id_raw=torneo_id_raw,
        fase_raw=fase_raw,
        require_torneo_active=False,
    )
    if err:
        base = _append_error_params(
            f"/informes-de-gastos/{cuenta_id}/editar",
            error_msg=err,
        )
        if tipo_ok:
            base += f"&tipo_cuenta={quote(tipo_ok)}"
        else:
            base += f"&tipo_cuenta={quote((tipo_cuenta_raw or 'local').strip().lower() or 'local')}"
        if nombre_val is not None:
            base += f"&nombre={quote(nombre_val or '')}"
        if torneo_id_raw:
            base += f"&torneo_id={quote(str(torneo_id_raw))}"
        if fase_raw:
            base += f"&fase={quote(fase_raw)}"
        return RedirectResponse(url=base, status_code=303)
    assert tipo_ok is not None and torneo_id_uuid is not None
    try:
        if hasattr(cuenta, "nombre"):
            cuenta.nombre = nombre_val
        cuenta.tipo_cuenta = tipo_ok
        cuenta.torneo_id = torneo_id_uuid
        cuenta.fase = fase_final
        await session.commit()
        return RedirectResponse(
            url=_append_success_params(
                f"/informes-de-gastos/{cuenta_id}",
                success="editada",
                msg="Clasificación y nombre actualizados.",
            ),
            status_code=303,
        )
    except (ProgrammingError, OperationalError):
        await session.rollback()
        return _schema_outdated_html_response()


async def _load_cfdi_autofill_bytes(
    *,
    xml_upload: Optional[UploadFile] = None,
    pdf_upload: Optional[UploadFile] = None,
) -> Tuple[Optional[bytes], Optional[bytes], Optional[str]]:
    xml_bytes: Optional[bytes] = None
    pdf_bytes: Optional[bytes] = None

    if xml_upload and xml_upload.filename:
        xml_bytes = await xml_upload.read()
        if not xml_bytes:
            return None, None, "El CFDI XML está vacío."
        if len(xml_bytes) > MAX_SOLICITUD_ATTACHMENT_BYTES:
            return None, None, "El CFDI XML excede el tamaño máximo permitido."

    if pdf_upload and pdf_upload.filename:
        pdf_bytes = await pdf_upload.read()
        if not pdf_bytes:
            return None, None, "El CFDI PDF está vacío."
        if len(pdf_bytes) > MAX_SOLICITUD_PDF_BYTES:
            return None, None, "El CFDI PDF excede el tamaño máximo permitido."
        if not is_pdf_content(pdf_bytes):
            return None, None, "El archivo debe ser un PDF válido."

    if not xml_bytes and not pdf_bytes:
        return None, None, "Adjunte un CFDI XML o PDF."

    return xml_bytes, pdf_bytes, None


@router.post("/api/documentos/cfdi-autofill", response_class=JSONResponse)
async def api_documentos_cfdi_autofill(
    current_empleado: Empleado = Depends(get_current_empleado),
    archivo_xml: Optional[UploadFile] = File(None),
    archivo_pdf: Optional[UploadFile] = File(None),
) -> JSONResponse:
    """
    Read CFDI XML or PDF and return form prefill values for solicitud a terceros.

    XML takes precedence when both files are supplied. Does not persist data.
    """
    del current_empleado  # auth gate only

    xml_bytes, pdf_bytes, load_error = await _load_cfdi_autofill_bytes(
        xml_upload=archivo_xml,
        pdf_upload=archivo_pdf,
    )
    if load_error:
        return JSONResponse(
            status_code=400,
            content={"ok": False, "error": load_error},
        )

    parsed, parse_error = parse_cfdi_for_autofill(
        xml_bytes=xml_bytes,
        pdf_bytes=pdf_bytes,
    )
    if parse_error:
        return JSONResponse(
            status_code=422 if parsed else 400,
            content={"ok": False, "error": parse_error},
        )

    autofill = autofill_from_parsed_cfdi(parsed)
    if not autofill:
        return JSONResponse(
            status_code=422,
            content={
                "ok": False,
                "error": "No se pudieron extraer datos del CFDI para precargar el formulario.",
            },
        )

    return JSONResponse(content={"ok": True, "data": autofill.to_dict()})


@router.post("/api/informes-de-gastos/cfdi-autofill", response_class=JSONResponse)
async def api_informes_cfdi_autofill(
    current_empleado: Empleado = Depends(get_current_empleado),
    cfdi_xml: Optional[UploadFile] = File(None),
    cfdi_pdf: Optional[UploadFile] = File(None),
) -> JSONResponse:
    """
    Read CFDI XML or PDF and return captura rápida prefill values.

    XML takes precedence when both files are supplied. Does not persist data.
    """
    del current_empleado  # auth gate only

    xml_bytes, pdf_bytes, load_error = await _load_cfdi_autofill_bytes(
        xml_upload=cfdi_xml,
        pdf_upload=cfdi_pdf,
    )
    if load_error:
        return JSONResponse(
            status_code=400,
            content={"ok": False, "error": load_error},
        )

    parsed, parse_error = parse_cfdi_for_autofill(
        xml_bytes=xml_bytes,
        pdf_bytes=pdf_bytes,
    )
    if parse_error:
        return JSONResponse(
            status_code=422 if parsed else 400,
            content={"ok": False, "error": parse_error},
        )

    autofill = autofill_quick_expense_from_parsed_cfdi(parsed)
    if not autofill:
        return JSONResponse(
            status_code=422,
            content={
                "ok": False,
                "error": "No se pudieron extraer datos del CFDI para precargar el formulario.",
            },
        )

    return JSONResponse(content={"ok": True, "data": autofill.to_dict()})


@router.get("/api/empleado-bank-accounts", response_class=JSONResponse)
async def api_empleado_bank_accounts(
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
    threshold: float = Query(_EMPLEADO_PROVEEDOR_NAME_SIMILARITY_THRESHOLD, ge=0.0, le=1.0),
    limit: int = Query(50, ge=1, le=100),
):
    """
    Return matching ProveedorCliente bank accounts for the current empleado based on name similarity.
    """
    matches = await _get_matching_bank_accounts_for_empleado(
        session=session,
        empleado=current_empleado,
        threshold=threshold,
        limit=limit,
    )
    items = []
    for proveedor, similarity in matches:
        items.append(
            {
                "id": str(proveedor.id),
                "nombre": proveedor.nombre,
                "banco": proveedor.banco,
                "cuenta_bancaria": proveedor.cuenta_bancaria,
                "cuenta_clabe": proveedor.cuenta_clabe,
                "similarity": similarity,
            }
        )
    return JSONResponse(content=items)


@router.get("/informes-de-gastos/{cuenta_id}/nueva-solicitud", response_class=HTMLResponse)
async def nueva_solicitud_desde_cuenta_form(
    cuenta_id: UUIDType,
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
) -> str:
    """
    Form to create a new SOLICITUD personal linked to this Cuenta de Gastos.
    """
    from html import escape
    cuenta_result = await session.execute(
        select(CuentaDeGastos)
        .where(CuentaDeGastos.id == cuenta_id)
        .options(
            undefer(CuentaDeGastos.torneo_id),
            undefer(CuentaDeGastos.categorias),
            undefer(CuentaDeGastos.edicion),
            undefer(CuentaDeGastos.currency),
            undefer(CuentaDeGastos.fase),
            selectinload(CuentaDeGastos.torneo),
        )
    )
    cuenta = cuenta_result.scalar_one_or_none()
    if not cuenta or (current_empleado.rol not in ('admin', 'finanzas') and cuenta.empleado_id != current_empleado.id):
        raise HTTPException(status_code=404, detail="Informe de Gastos no encontrado")
    if cuenta.estado == 'cerrada':
        raise HTTPException(status_code=400, detail="No se pueden crear solicitudes en un informe de gastos cerrado")

    # Preload matching bank accounts for this empleado (server-rendered dropdown)
    matches = await _get_matching_bank_accounts_for_empleado(session=session, empleado=current_empleado)
    bank_account_options = '<option value="" disabled selected data-is-placeholder="true">— Seleccione cuenta bancaria —</option>'
    for proveedor, similarity in matches:
        nombre_escaped = escape(proveedor.nombre or "")
        banco_escaped = escape((proveedor.banco or "").strip())
        cuenta_escaped = escape((proveedor.cuenta_bancaria or "").strip())
        clabe_escaped = escape((proveedor.cuenta_clabe or "").strip())
        # Use last 4 digits of account or CLABE when available; avoid showing full number
        raw_account = (proveedor.cuenta_bancaria or "") or (proveedor.cuenta_clabe or "")
        last4 = ""
        if raw_account and len(raw_account) >= 4:
            last4 = raw_account[-4:]
        u4_escaped = escape(last4) if last4 else ""
        label_parts = [nombre_escaped]
        if banco_escaped:
            label_parts.append(f"— {banco_escaped}")
        if last4:
            label_parts.append(f"(…{last4})")
        label = " ".join(label_parts)
        bank_account_options += (
            f'<option value="{proveedor.id}" data-banco="{banco_escaped}" '
            f'data-cuenta="{cuenta_escaped}" data-cuenta-clabe="{clabe_escaped}" '
            f'data-ultimos4="{u4_escaped}">{label}</option>'
        )

    informe_doc = await _informe_documento_for_cuenta(session, cuenta.id)
    ro_existing = (informe_doc.referencia_operaciones or "").strip() if informe_doc else ""
    if ro_existing:
        ro_display_value = escape(ro_existing)
        ro_help_text = (
            "Referencia operaciones del informe (se reutiliza en la solicitud)."
        )
    elif empleado_allocates_referencia_operaciones(current_empleado):
        ro_display_value = escape(
            "Se asignará al crear la solicitud (mismo número que el informe)"
        )
        ro_help_text = "Se asigna automáticamente por el sistema (igual que el informe)."
    else:
        ro_na_value, ro_na_help = referencia_operaciones_form_display(current_empleado)
        ro_display_value = escape(ro_na_value)
        ro_help_text = ro_na_help

    error_msg = request.query_params.get("error_msg", "")
    fecha_pago_kwargs = st_fecha_pago_form_kwargs()
    cuenta_fase_raw = ""
    try:
        raw_fase = getattr(cuenta, "fase", None)
        cuenta_fase_raw = (str(raw_fase).strip() if raw_fase is not None else "") or ""
    except (ProgrammingError, OperationalError):
        cuenta_fase_raw = ""
    cuenta_proyecto_display = format_solicitud_proyecto_display(
        cuenta.torneo.name if cuenta.torneo else None,
        fase=cuenta_fase_raw or None,
        categorias=getattr(cuenta, "categorias", None),
        edicion=getattr(cuenta, "edicion", None),
    ) or "—"
    html = f"""
    <!DOCTYPE html>
    <html>
    <head>
        <title>Nueva Solicitud - Informe {cuenta.referencia_base}</title>
        <style>
            {_workspace_shell_styles("920px")}
            {solicitud_transferencia_doc_styles()}
            .notice.warn {{
                background: #fef2f2;
                color: #991b1b;
                border: 1px solid #fecaca;
                border-radius: 12px;
                padding: 12px 14px;
                margin-bottom: 16px;
            }}
            .informe-context {{
                color: #475569;
                margin: 0 0 16px;
                font-size: 14px;
            }}
        </style>
    </head>
    <body>
        <div class="container">
            {render_top_navigation(current_empleado, "informes")}
            <h1 style="margin-top:0;">Nueva solicitud de transferencia</h1>
            <p class="informe-context">Informe: {escape(cuenta.referencia_base)}</p>
            {f'<div class="notice warn">{escape(error_msg)}</div>' if error_msg else ''}
            <form method="POST" action="/informes-de-gastos/{cuenta.id}/nueva-solicitud">
                <div class="st-page-wrap">
                    <div class="st-doc">
                        {render_st_doc_header_form()}
                        {render_st_doc_row(
                            "BENEFICIARIO:",
                            f'''<div>
                                <div id="st_preview_beneficiario" style="margin-bottom:8px;">{escape(current_empleado.nombre or "")}</div>
                                <select name="proveedor_cliente_id" id="proveedor_cliente_id" required>
                                    {bank_account_options}
                                </select>
                                <small>Seleccione la cuenta bancaria para la transferencia.</small>
                            </div>''',
                        )}
                        {render_st_doc_row(
                            "BANCO:",
                            '<span id="st_preview_banco" class="st-doc-firma-name" style="display:block;width:100%;">—</span>',
                            readonly=True,
                        )}
                        {render_st_doc_row_cuenta(
                            '<span id="st_preview_cuenta">—</span>',
                            '<span id="st_preview_clabe">—</span>',
                            readonly=True,
                        )}
                        {render_st_doc_row(
                            "CANTIDAD A PAGAR:",
                            f'''<div style="display:grid;grid-template-columns:1fr 110px;gap:8px;">
                                <input type="text" id="monto_solicitado_display" inputmode="decimal" required autocomplete="off" placeholder="0.00">
                                <input type="hidden" name="monto_solicitado" id="monto_solicitado" value="">
                                <input type="text" value="{escape(currency_for(cuenta))}" readonly aria-label="Moneda">
                            </div>''',
                        )}
                        {render_st_doc_row(
                            "CANTIDAD CON LETRA:",
                            '<textarea id="monto_solicitado_letra" rows="2" readonly></textarea>',
                            readonly=True,
                        )}
                        {render_st_doc_row_dual(
                            "PROYECTO:",
                            f'''<div>
                                <strong>{escape(cuenta_proyecto_display)}</strong>
                                <small>Moneda del informe: {escape(currency_for(cuenta))}</small>
                            </div>''',
                            "FECHA DE PAGO:",
                            render_st_fecha_pago_field(**fecha_pago_kwargs),
                            left_readonly=True,
                        )}
                        {render_st_doc_row(
                            "PAGO URGENTE:",
                            render_pago_urgente_field(),
                        )}
                        {render_st_doc_row(
                            "DESCRIPCIÓN:",
                            '<input type="text" name="concepto_pago" id="concepto_pago" required>',
                        )}
                        {render_st_doc_row_dual(
                            "NÚMERO DE FACTURA:",
                            '<span>—</span>',
                            "REFERENCIA:",
                            f'<input type="text" id="referencia_operaciones_display" readonly value="{ro_display_value}"><small>{escape(ro_help_text)}</small>',
                            left_readonly=True,
                            right_readonly=True,
                        )}
                        {render_st_doc_firmas(escape(current_empleado.nombre or ""), "")}
                    </div>
                </div>
                <div class="st-form-actions">
                    <button type="submit" class="button primary">Crear solicitud</button>
                    <a href="/informes-de-gastos/{cuenta.id}" class="button secondary">Cancelar</a>
                </div>
            </form>
        </div>
        {render_proveedor_bank_preview_script()}
        {_render_auto_number_formatter_script([
            {
                "displayId": "monto_solicitado_display",
                "rawId": "monto_solicitado",
                "wordsPreviewId": "monto_solicitado_letra",
                "currency": currency_for(cuenta),
            }
        ])}
    </body>
    </html>
    """
    return html


@router.post("/informes-de-gastos/{cuenta_id}/nueva-solicitud")
async def nueva_solicitud_desde_cuenta_submit(
    cuenta_id: UUIDType,
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
) -> RedirectResponse:
    """
    Create a SOLICITUD personal linked to this Cuenta de Gastos.
    Requires: monto_solicitado, concepto_pago.
    """
    form_data = await request.form()
    monto_str = (form_data.get("monto_solicitado") or "").strip()
    concepto_pago = (form_data.get("concepto_pago") or "").strip()
    proveedor_cliente_id_raw = (form_data.get("proveedor_cliente_id") or "").strip()
    pago_urgente = form_data.get("pago_urgente") in ("1", "true", "on", "yes")
    cuenta_result = await session.execute(select(CuentaDeGastos).where(CuentaDeGastos.id == cuenta_id))
    cuenta = cuenta_result.scalar_one_or_none()
    if not cuenta or (current_empleado.rol not in ('admin', 'finanzas') and cuenta.empleado_id != current_empleado.id):
        raise HTTPException(status_code=404, detail="Informe de Gastos no encontrado")
    if cuenta.estado == 'cerrada':
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}",
                error="cuenta_cerrada",
            ),
            status_code=303,
        )

    # Optional: selected proveedor/cliente bank account for this empleado
    selected_proveedor = None
    if proveedor_cliente_id_raw:
        try:
            proveedor_uuid = UUIDType(proveedor_cliente_id_raw)
        except (ValueError, TypeError):
            proveedor_uuid = None
        if proveedor_uuid is not None:
            # Security: recompute allowed matches for this empleado and require id to be in that set
            matches = await _get_matching_bank_accounts_for_empleado(session=session, empleado=current_empleado)
            allowed_ids = {prov.id for prov, _ in matches}
            if proveedor_uuid in allowed_ids:
                proveedor_result = await session.execute(
                    select(ProveedorCliente).where(
                        and_(
                            ProveedorCliente.id == proveedor_uuid,
                            ProveedorCliente.activo == True,
                        )
                    )
                )
                selected_proveedor = proveedor_result.scalar_one_or_none()
    try:
        payload = build_solicitud_personal_payload(
            cuenta_id=cuenta_id,
            empleado_id=current_empleado.id,
            monto_solicitado=monto_str,
            concepto_pago=concepto_pago,
            proveedor_cliente_id=(
                str(selected_proveedor.id) if selected_proveedor is not None else None
            ),
            pago_urgente=pago_urgente,
        )
        await create_solicitud_personal_document(session, payload)
    except SolicitudValidationError as exc:
        await session.rollback()
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}/nueva-solicitud",
                error_msg=f"{str(exc)}.",
            ),
            status_code=303,
        )
    except Exception:
        await session.rollback()
        logger.exception(
            "Unexpected error creating solicitud personal from cuenta",
            extra={
                "cuenta_id": str(cuenta_id),
                "empleado_id": str(current_empleado.id),
                "proveedor_cliente_id": proveedor_cliente_id_raw,
            },
        )
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}/nueva-solicitud",
                error="unexpected_solicitud_personal_create",
                error_msg=(
                    "Ocurrió un error al procesar la solicitud. "
                    "Revise los datos capturados e intente nuevamente."
                ),
            ),
            status_code=303,
        )

    return RedirectResponse(
        url=_append_success_params(
            f"/informes-de-gastos/{cuenta_id}",
            success="solicitud_creada",
            msg="Solicitud creada. Puede enviarla para aprobación desde el enlace del documento.",
        ),
        status_code=303
    )


@router.post("/informes-de-gastos/{cuenta_id}/cerrar")
async def cerrar_cuenta_de_gastos(
    cuenta_id: UUIDType,
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
    next: Optional[str] = Form(None),
    proveedor_cliente_id: Optional[str] = Form(None),
) -> RedirectResponse:
    """
    Close a Cuenta de Gastos and send its linked INFORME document to approval.

    When the cuenta has saldo a favor del empleado, also auto-generate (and send)
    a reembolso SOLICITUD de transferencia to the bank account selected in the
    Saldo box, so it lands in pagos pendientes once the INFORME is approved.
    """
    # Fetch cuenta
    cuenta_result = await session.execute(
        select(CuentaDeGastos).where(CuentaDeGastos.id == cuenta_id)
    )
    cuenta = cuenta_result.scalar_one_or_none()

    if not cuenta:
        raise HTTPException(status_code=404, detail="Informe de Gastos no encontrado")

    # Check ownership (unless admin/finanzas)
    if current_empleado.rol not in ('admin', 'finanzas', 'superadmin', 'super_admin') and cuenta.empleado_id != current_empleado.id:
        raise HTTPException(status_code=403, detail="No tienes permiso para cerrar este informe de gastos")

    informe_doc = await _informe_documento_for_cuenta(session, cuenta_id)
    if informe_doc is None:
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}",
                error="no_informe_doc",
                error_msg="Este informe no tiene documento INFORME vinculado.",
            ),
            status_code=303,
        )

    redirect_url = _safe_internal_next(next, f"/informes-de-gastos/{cuenta_id}")

    if cuenta.estado not in {"abierta", "cerrada"}:
        return RedirectResponse(
            url=_append_query_params(
                redirect_url,
                {
                    "error": "invalid_estado",
                    "error_msg": "El informe no está en un estado que pueda cerrarse.",
                },
            ),
            status_code=303,
        )

    # Saldo a favor del empleado: auto-generate a reembolso SOLICITUD before
    # closing (create_solicitud_personal_document rejects a closed cuenta).
    reembolso_warning: Optional[str] = None
    reembolso_created = False
    if cuenta.estado == "abierta":
        saldo_ctx = await _compute_cuenta_saldo_context(session, cuenta_id)
        saldo_raw = float(saldo_ctx.get("saldo_raw") or 0)
        if saldo_raw < -0.005:
            provider_beneficiary_id = effective_account_provider_beneficiary_id(cuenta)
            beneficiary_id = effective_account_beneficiary_id(cuenta)
            existing_filters = [
                Documento.cuenta_gastos_id == cuenta_id,
                Documento.tipo == "SOLICITUD",
                Documento.concepto_pago.like("Reembolso de saldo a favor%"),
                Documento.estado.notin_(["rechazado", "cancelado"]),
            ]
            if provider_beneficiary_id is not None:
                existing_filters.append(
                    Documento.beneficiario_proveedor_cliente_id == provider_beneficiary_id
                )
            else:
                existing_filters.append(Documento.beneficiario_empleado_id == beneficiary_id)
            existing_reembolso = await session.execute(
                select(Documento.id).where(*existing_filters).limit(1)
            )
            if existing_reembolso.scalar_one_or_none() is None:
                proveedor_uuid: Optional[UUIDType] = None
                proveedor_raw = (proveedor_cliente_id or "").strip()
                if proveedor_raw:
                    try:
                        proveedor_uuid = UUIDType(proveedor_raw)
                    except (ValueError, TypeError):
                        proveedor_uuid = None
                if provider_beneficiary_id is not None:
                    provider_result = await session.execute(
                        select(ProveedorCliente).where(
                            and_(
                                ProveedorCliente.id == provider_beneficiary_id,
                                ProveedorCliente.activo == True,
                            )
                        )
                    )
                    provider_beneficiary = provider_result.scalar_one_or_none()
                    if (
                        provider_beneficiary is None
                        or proveedor_uuid != provider_beneficiary_id
                    ):
                        return RedirectResponse(
                            url=_append_query_params(
                                redirect_url,
                                {
                                    "error": "invalid_bank_account",
                                    "error_msg": (
                                        "Seleccione la cuenta bancaria del operador "
                                        "regional beneficiario antes de cerrar el informe."
                                    ),
                                },
                            ),
                            status_code=303,
                        )
                else:
                    owner_result = await session.execute(
                        select(Empleado).where(Empleado.id == beneficiary_id)
                    )
                    beneficiary_empleado = owner_result.scalar_one_or_none()
                    matches = (
                        await _get_matching_bank_accounts_for_empleado(
                            session=session, empleado=beneficiary_empleado
                        )
                        if beneficiary_empleado is not None
                        else []
                    )
                    allowed_ids = {prov.id for prov, _ in matches}
                    if proveedor_uuid is None or proveedor_uuid not in allowed_ids:
                        return RedirectResponse(
                            url=_append_query_params(
                                redirect_url,
                                {
                                    "error": "invalid_bank_account",
                                    "error_msg": (
                                        "Seleccione una cuenta bancaria válida del "
                                        "beneficiario para el reembolso del saldo a favor "
                                        "antes de cerrar el informe."
                                    ),
                                },
                            ),
                            status_code=303,
                        )
                try:
                    payload = build_solicitud_personal_payload(
                        cuenta_id=cuenta_id,
                        empleado_id=cuenta.empleado_id,
                        monto_solicitado=abs(saldo_raw),
                        concepto_pago=reimbursement_concept_from_cuenta(cuenta),
                        proveedor_cliente_id=str(proveedor_uuid),
                        budget_concept_id=(
                            str(informe_doc.budget_concept_id)
                            if informe_doc.budget_concept_id
                            else None
                        ),
                    )
                    new_solicitud = await create_solicitud_personal_document(
                        session, payload
                    )
                except SolicitudValidationError as exc:
                    await session.rollback()
                    return RedirectResponse(
                        url=_append_query_params(
                            redirect_url,
                            {
                                "error": exc.code,
                                "error_msg": (
                                    f"No se pudo generar la solicitud de reembolso: "
                                    f"{exc.message}"
                                ),
                            },
                        ),
                        status_code=303,
                    )
                reembolso_created = True
                try:
                    await transition_documento_workflow(
                        session,
                        documento_id=new_solicitud.id,
                        actor_id=cuenta.empleado_id,
                        action="send",
                        comentario=(
                            "Generada al cerrar el informe "
                            "(saldo a favor del empleado)."
                        ),
                        request_context=audit_context_from_request(request),
                    )
                except Exception:
                    logger.exception(
                        "Failed to send auto-generated reembolso solicitud",
                        extra={
                            "cuenta_id": str(cuenta_id),
                            "solicitud_id": str(new_solicitud.id),
                        },
                    )
                    reembolso_warning = (
                        " La solicitud de reembolso se creó pero no pudo enviarse "
                        "automáticamente; envíela manualmente desde el documento."
                    )

    try:
        doc_synced = await _sync_informe_documento_to_enviado(
            session,
            cuenta=cuenta,
            informe_doc=informe_doc,
            actor=current_empleado,
        )
    except DocumentoWorkflowValidationError as exc:
        return RedirectResponse(
            url=_append_query_params(
                redirect_url,
                {"error": exc.code, "error_msg": exc.message},
            ),
            status_code=303,
        )

    cuenta_was_closed = cuenta.estado == "cerrada"
    if not cuenta_was_closed:
        cuenta.estado = "cerrada"
        cuenta.closed_at = datetime.utcnow()

    if cuenta_was_closed and not doc_synced:
        return RedirectResponse(
            url=_append_query_params(
                redirect_url,
                {"error": "already_closed", "error_msg": "El informe ya estaba cerrado."},
            ),
            status_code=303,
        )

    await session.commit()
    if doc_synced:
        await record_customer_success_audit_event(
            session,
            action="documento.sent",
            actor_empleado_id=current_empleado.id,
            target_empleado_id=informe_doc.empleado_id,
            documento_id=informe_doc.id,
            documento_referencia=informe_doc.numero_referencia,
            surface="web",
            request_context=audit_context_from_request(request),
            summary=(
                "Informe enviado automáticamente al cerrar la cuenta de gastos"
            ),
            metadata={
                "documento_tipo": informe_doc.tipo,
                "cuenta_id": str(cuenta_id),
                "auto_sent": True,
            },
            commit=True,
        )
        try:
            if informe_doc.estado == "control_presupuestal":
                from ..services.documento_telegram import (
                    schedule_budget_control_telegram_notifications,
                )

                schedule_budget_control_telegram_notifications(
                    documento_id=str(informe_doc.id),
                    actor_id=str(current_empleado.id),
                )
            else:
                from ..services.documento_telegram import (
                    schedule_document_workflow_telegram_notifications,
                )

                schedule_document_workflow_telegram_notifications(
                    documento_id=str(informe_doc.id),
                    action="send",
                    actor_id=str(current_empleado.id),
                    comentario="Enviado automaticamente al cerrar el informe de gastos.",
                )
        except Exception:
            logger.exception(
                "Failed to schedule Telegram notification for informe close"
            )

    if informe_doc.estado == "control_presupuestal":
        success_msg = (
            "Informe cerrado y enviado a Control Presupuestal."
            if not cuenta_was_closed
            else "Documento de informe sincronizado y enviado a Control Presupuestal."
        )
    else:
        success_msg = (
            "Informe cerrado y enviado para aprobaci?n."
            if not cuenta_was_closed
            else "Documento de informe sincronizado y enviado para aprobaci?n."
        )
    if reembolso_created:
        success_msg += (
            " Se generó una solicitud de transferencia por el saldo a favor del "
            "empleado."
        )
    if reembolso_warning:
        success_msg += reembolso_warning
    return RedirectResponse(
        url=_append_query_params(
            redirect_url,
            {"success": "cerrada", "msg": success_msg},
        ),
        status_code=303
    )


