# Saldar cuenta (reembolso / devolucion) — v1.0.24
# =============================================================================


async def _compute_cuenta_saldo_context(
    session: AsyncSession, cuenta_id: UUIDType
) -> Dict[str, Any]:
    """Return saldo context used by the saldar UI and POST validation."""
    gastos_row = await session.execute(
        select(func.coalesce(func.sum(ExpenseReport.gasto_cantidad), 0)).where(
            ExpenseReport.cuenta_gastos_id == cuenta_id,
            ExpenseReport.estado_gasto != "cancelado",
            employee_paid_sql_condition(),
        )
    )
    total_pagado_empleado = float(gastos_row.scalar_one() or 0)

    solicitado_row = await session.execute(
        select(func.coalesce(func.sum(Documento.monto_solicitado), 0)).where(
            Documento.cuenta_gastos_id == cuenta_id,
            Documento.tipo == "SOLICITUD",
            Documento.estado == "pagado",
        )
    )
    monto_entregado = float(solicitado_row.scalar_one() or 0)

    settled_amount, active_count = await compute_cuenta_saldo_adjustments(
        session, cuenta_id
    )
    saldo_breakdown = compute_informe_saldo(
        employee_paid=total_pagado_empleado,
        monto_entregado=monto_entregado,
        settled_amount=settled_amount,
    )
    return {
        "total_gastos": total_pagado_empleado,
        "total_pagado_empleado": total_pagado_empleado,
        "monto_solicitado": monto_entregado,
        "monto_entregado": monto_entregado,
        "settled_amount": settled_amount,
        "active_settlement_count": active_count,
        "saldo_gross": saldo_breakdown.saldo_gross,
        "saldo_raw": saldo_breakdown.saldo,
        "tipo": saldo_breakdown.settlement_tipo,
    }


def _can_access_reembolso_cuenta(cuenta: CuentaDeGastos, empleado: Empleado) -> bool:
    if cuenta.empleado_id == empleado.id:
        return True
    rol = (empleado.rol or "").strip().lower()
    return rol in {"admin", "finanzas", "coordinador", "superadmin", "super_admin"}


def _can_submit_settlement(
    cuenta: CuentaDeGastos, empleado: Empleado, tipo: str
) -> bool:
    rol = (empleado.rol or "").strip().lower()
    if tipo == "reembolso":
        return rol in {"admin", "finanzas", "superadmin", "super_admin"}
    if tipo == "devolucion":
        return cuenta.empleado_id == empleado.id or rol in {
            "admin", "finanzas", "superadmin", "super_admin"
        }
    return False


@router.get("/informes-de-gastos/{cuenta_id}/saldar", response_class=HTMLResponse)
async def saldar_cuenta_form(
    cuenta_id: UUIDType,
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
) -> str:
    """Render the 'Saldar cuenta' settlement form."""
    cuenta_result = await session.execute(
        select(CuentaDeGastos).where(CuentaDeGastos.id == cuenta_id)
    )
    cuenta = cuenta_result.scalar_one_or_none()
    if cuenta is None:
        raise HTTPException(status_code=404, detail="Informe de Gastos no encontrado")
    if not _can_access_reembolso_cuenta(cuenta, current_empleado):
        raise HTTPException(status_code=403, detail="Acceso denegado")

    informe_doc = await _informe_documento_for_cuenta(session, cuenta_id)
    empleado_result = await session.execute(
        select(Empleado).where(Empleado.id == cuenta.empleado_id)
    )
    empleado_cuenta = empleado_result.scalar_one_or_none()

    saldo_ctx = await _compute_cuenta_saldo_context(session, cuenta_id)
    tipo = saldo_ctx["tipo"]
    saldo_abs = abs(float(saldo_ctx["saldo_raw"] or 0))
    error_msg = request.query_params.get("error_msg", "")

    notice_html = ""
    blocked = False
    if informe_doc is None:
        blocked = True
        notice_html = (
            '<div class="notice warn"><strong>Sin documento INFORME.</strong> '
            'No se puede liquidar una cuenta sin documento vinculado.</div>'
        )
    elif informe_doc.estado != "aprobado":
        blocked = True
        notice_html = (
            '<div class="notice warn"><strong>Informe no aprobado.</strong> '
            'La liquidación se habilita cuando el informe sea aprobado.</div>'
        )
    elif saldo_ctx["active_settlement_count"] > 0:
        blocked = True
        notice_html = (
            '<div class="notice warn"><strong>Ya existe una liquidación activa.</strong> '
            'Cancélala antes de registrar otra.</div>'
        )
    elif tipo is None:
        blocked = True
        notice_html = (
            '<div class="notice success"><strong>Cuenta saldada.</strong> '
            'No hay saldo pendiente por liquidar.</div>'
        )
    elif not _can_submit_settlement(cuenta, current_empleado, tipo):
        blocked = True
        if tipo == "reembolso":
            notice_html = (
                '<div class="notice warn">Solo finanzas puede registrar un reembolso al empleado. '
                'El empleado debe esperar a que finanzas liquide.</div>'
            )
        else:
            notice_html = (
                '<div class="notice warn">Solo el dueño del informe o finanzas pueden registrar una devolución.</div>'
            )

    if error_msg:
        notice_html = (
            f'<div class="notice warn">{escape(error_msg)}</div>' + notice_html
        )

    if tipo == "reembolso":
        direction_title = "Reembolso al empleado"
        direction_desc = (
            "La empresa debe reembolsar al empleado el saldo pendiente."
        )
        pagador_label = f"{current_empleado.nombre} (finanzas)"
        receptor_label = empleado_cuenta.nombre if empleado_cuenta else "—"
    elif tipo == "devolucion":
        direction_title = "Devolución a la empresa"
        direction_desc = (
            "El empleado debe devolver a la empresa el saldo pendiente."
        )
        pagador_label = f"{current_empleado.nombre} (registra)"
        receptor_label = "Tesorería / cuenta de empresa"
    else:
        direction_title = "Sin saldo pendiente"
        direction_desc = "No hay movimientos por liquidar."
        pagador_label = "—"
        receptor_label = "—"

    form_html = ""
    if not blocked:
        today_iso = date.today().isoformat()
        saldo_display = format_currency(saldo_abs)
        form_html = f"""
        <form method="POST" action="/informes-de-gastos/{cuenta_id}/saldar"
              enctype="multipart/form-data" class="surface" style="padding:20px;">
            <div class="form-group">
                <label>Tipo</label>
                <div><strong>{escape(direction_title)}</strong></div>
                <div class="section-note">{escape(direction_desc)}</div>
            </div>
            <div class="form-group">
                <label>Monto a liquidar</label>
                <div style="font-size:1.3rem;"><strong>{saldo_display}</strong> MXN</div>
                <input type="hidden" name="monto" value="{saldo_abs:.2f}">
                <input type="hidden" name="saldo_snapshot" value="{saldo_abs:.2f}">
                <div class="section-note">Se liquida el saldo completo; no se permiten pagos parciales.</div>
            </div>
            <div class="form-group">
                <label for="metodo_pago_sld">Método de pago</label>
                <select name="metodo_pago" id="metodo_pago_sld">
                    <option value="transferencia">Transferencia bancaria</option>
                    <option value="efectivo">Efectivo</option>
                    <option value="cheque">Cheque</option>
                    <option value="tarjeta">Tarjeta</option>
                    <option value="otro">Otro</option>
                </select>
            </div>
            <div class="form-group">
                <label for="fecha_pago_sld">Fecha del pago</label>
                <input type="date" name="fecha_pago" id="fecha_pago_sld" value="{today_iso}">
            </div>
            <div class="form-group">
                <label for="referencia_pago_sld">Referencia / folio</label>
                <input type="text" name="referencia_pago" id="referencia_pago_sld"
                       maxlength="255" placeholder="Folio SPEI, últimos 4 de cuenta, etc.">
            </div>
            <div class="form-group">
                <label for="comprobante_sld">Comprobante (PDF / JPG / PNG) *</label>
                <input type="file" name="comprobante" id="comprobante_sld"
                       accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" required>
                <div class="section-note">Adjunta el comprobante de la transferencia o depósito.</div>
            </div>
            <div class="form-group">
                <label for="notas_sld">Notas (opcional)</label>
                <textarea name="notas" id="notas_sld" rows="3"
                          placeholder="Contexto adicional del movimiento."></textarea>
            </div>
            <div class="inline-actions">
                <button type="submit" class="button primary">Registrar liquidación</button>
                <a href="/informes-de-gastos/{cuenta_id}" class="button secondary">Cancelar</a>
            </div>
        </form>
        """

    side_html = f"""
        <div class="eyebrow">Dirección</div>
        <div class="status-chip info" style="margin-top:6px;">{escape(direction_title)}</div>
        <div class="meta-grid">
            <div class="meta-card">
                <span>Paga</span>
                <strong>{escape(pagador_label)}</strong>
            </div>
            <div class="meta-card">
                <span>Recibe</span>
                <strong>{escape(receptor_label)}</strong>
            </div>
            <div class="meta-card">
                <span>Gastos de bolsillo</span>
                <strong>{format_currency(saldo_ctx["total_pagado_empleado"])}</strong>
                <small>Sin contar AMEX empresa.</small>
            </div>
            <div class="meta-card">
                <span>Entregado por la empresa</span>
                <strong>{format_currency(saldo_ctx["monto_entregado"])}</strong>
                <small>Solicitudes ya pagadas.</small>
            </div>
            <div class="meta-card">
                <span>Saldo actual</span>
                <strong>{format_currency(saldo_abs)}</strong>
                <small>Monto exacto a liquidar.</small>
            </div>
        </div>
    """

    actions_html = f"""
        <a href="/informes-de-gastos/{cuenta_id}" class="button secondary">Volver al informe</a>
    """

    html = f"""
    <!DOCTYPE html>
    <html>
    <head>
        <title>Saldar cuenta — I-{escape(cuenta.referencia_base)}</title>
        <style>
            {_workspace_shell_styles("1024px")}
        </style>
    </head>
    <body>
        <div class="container">
            {render_top_navigation(current_empleado, "informes")}
            {_render_workspace_hero(
                eyebrow="Operación",
                title=f"Saldar cuenta I-{escape(cuenta.referencia_base)}",
                description="Registra el movimiento que cierra el saldo pendiente del informe.",
                actions_html=actions_html,
                side_html=side_html,
            )}
            <div class="stack">
                {notice_html}
                {form_html}
            </div>
        </div>
    </body>
    </html>
    """
    return html


@router.post("/informes-de-gastos/{cuenta_id}/saldar")
async def saldar_cuenta_submit(
    cuenta_id: UUIDType,
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
    monto: str = Form(...),
    saldo_snapshot: Optional[str] = Form(None),
    moneda: str = Form("MXN"),
    metodo_pago: Optional[str] = Form(None),
    fecha_pago: Optional[str] = Form(None),
    referencia_pago: Optional[str] = Form(None),
    notas: Optional[str] = Form(None),
    comprobante: Optional[UploadFile] = File(None),
) -> RedirectResponse:
    """Register a full-settlement reembolso/devolucion for the cuenta."""
    cuenta_row = await session.execute(
        select(CuentaDeGastos).where(CuentaDeGastos.id == cuenta_id)
    )
    cuenta = cuenta_row.scalar_one_or_none()
    if cuenta is None:
        raise HTTPException(status_code=404, detail="Informe de Gastos no encontrado")
    if not _can_access_reembolso_cuenta(cuenta, current_empleado):
        raise HTTPException(status_code=403, detail="Acceso denegado")

    informe_doc = await _informe_documento_for_cuenta(session, cuenta_id)
    if informe_doc is None or informe_doc.estado != "aprobado":
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}/saldar",
                error="informe_not_approved",
                error_msg="La cuenta solo puede liquidarse cuando el informe esté aprobado.",
            ),
            status_code=303,
        )

    comprobante_bytes: Optional[bytes] = None
    comprobante_filename: Optional[str] = None
    comprobante_mime: Optional[str] = None
    if comprobante is not None:
        comprobante_bytes = await comprobante.read()
        comprobante_filename = comprobante.filename
        comprobante_mime = comprobante.content_type

    try:
        result = await register_cuenta_settlement(
            session,
            cuenta_id=cuenta_id,
            actor_id=current_empleado.id,
            monto=monto,
            moneda=moneda,
            metodo_pago=metodo_pago,
            fecha_pago=fecha_pago,
            referencia_pago=referencia_pago,
            notas=notas,
            comprobante_bytes=comprobante_bytes,
            comprobante_filename=comprobante_filename,
            comprobante_mime=comprobante_mime,
            saldo_snapshot=saldo_snapshot,
        )
    except CuentaSettlementPermissionError as exc:
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}/saldar",
                error=exc.code,
                error_msg=exc.message,
            ),
            status_code=303,
        )
    except CuentaSettlementValidationError as exc:
        if exc.code == "cuenta_not_found":
            raise HTTPException(status_code=404, detail=exc.message)
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}/saldar",
                error=exc.code,
                error_msg=exc.message,
            ),
            status_code=303,
        )
    except Exception:
        await session.rollback()
        logger.exception(
            "Unexpected error settling cuenta de gastos",
            extra={
                "cuenta_id": str(cuenta_id),
                "actor_id": str(current_empleado.id),
            },
        )
        return RedirectResponse(
            url=_append_error_params(
                f"/informes-de-gastos/{cuenta_id}/saldar",
                error="unexpected_cuenta_settlement",
                error_msg=(
                    "Ocurrió un error al registrar la operación. "
                    "Intente nuevamente."
                ),
            ),
            status_code=303,
        )

    logger.info(
        "Cuenta %s saldada por %s (tipo=%s, monto=%s)",
        cuenta_id,
        current_empleado.id,
        result.tipo,
        monto,
    )
    label = "Reembolso" if result.tipo == "reembolso" else "Devolución"
    success_msg = f"{label} registrado exitosamente. Cuenta saldada."
    return RedirectResponse(
        url=_append_success_params(
            f"/informes-de-gastos/{cuenta_id}",
            success="saldada",
            msg=success_msg,
        ),
        status_code=303,
    )


@router.get(
    "/informes-de-gastos/{cuenta_id}/reembolsos/{reembolso_id}",
    response_class=HTMLResponse,
)
async def ver_reembolso_cuenta(
    cuenta_id: UUIDType,
    reembolso_id: UUIDType,
    request: Request,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
) -> str:
    """Detail page for a specific reembolso/devolucion row."""
    cuenta_result = await session.execute(
        select(CuentaDeGastos).where(CuentaDeGastos.id == cuenta_id)
    )
    cuenta = cuenta_result.scalar_one_or_none()
    if cuenta is None:
        raise HTTPException(status_code=404, detail="Informe de Gastos no encontrado")
    if not _can_access_reembolso_cuenta(cuenta, current_empleado):
        raise HTTPException(status_code=403, detail="Acceso denegado")

    reembolso_result = await session.execute(
        select(Reembolso).where(
            Reembolso.id == reembolso_id,
            Reembolso.cuenta_gastos_id == cuenta_id,
        )
    )
    reembolso = reembolso_result.scalar_one_or_none()
    if reembolso is None:
        raise HTTPException(status_code=404, detail="Liquidación no encontrada")

    pagador = None
    if reembolso.pagador_empleado_id:
        pagador_row = await session.execute(
            select(Empleado).where(Empleado.id == reembolso.pagador_empleado_id)
        )
        pagador = pagador_row.scalar_one_or_none()
    cancelador = None
    if reembolso.cancelado_por_id:
        cancelador_row = await session.execute(
            select(Empleado).where(Empleado.id == reembolso.cancelado_por_id)
        )
        cancelador = cancelador_row.scalar_one_or_none()

    adjuntos_map = await fetch_reembolso_adjuntos_meta_batch(
        session, [reembolso.id]
    )
    adj_list = adjuntos_map.get(reembolso.id, [])

    tipo_label = "Reembolso al empleado" if reembolso.tipo == "reembolso" else "Devolución a la empresa"
    estado_label = (reembolso.estado or "").capitalize() or "—"
    fecha_pago_str = reembolso.fecha_pago.strftime("%Y-%m-%d") if reembolso.fecha_pago else "—"
    pagador_nombre = pagador.nombre if pagador else "—"

    adj_cell_html = "—"
    if adj_list:
        parts: List[str] = []
        for idx, meta in enumerate(adj_list, start=1):
            label = (
                (meta.nombre_archivo or f"Comprobante {idx}").strip()
                or f"Comprobante {idx}"
            )
            href = (
                f"/informes-de-gastos/{cuenta_id}/reembolsos/{reembolso_id}"
                f"/adjuntos/{meta.id}"
            )
            parts.append(
                f'<a href="{href}" target="_blank" rel="noopener">{escape(label)}</a>'
            )
        adj_cell_html = " · ".join(parts)

    cancel_form = ""
    rol_actor = (current_empleado.rol or "").strip().lower()
    if (
        reembolso.estado != "cancelado"
        and rol_actor in {"admin", "finanzas", "superadmin", "super_admin"}
    ):
        cancel_form = f"""
        <form method="POST" action="/informes-de-gastos/{cuenta_id}/reembolsos/{reembolso_id}/cancelar"
              style="margin-top:18px;">
            <div class="form-group">
                <label for="motivo_cancel">Motivo de cancelación *</label>
                <textarea name="motivo" id="motivo_cancel" required rows="3"
                          placeholder="Describe por qué se cancela."></textarea>
            </div>
            <button type="submit" class="button danger"
                    onclick="return confirm('¿Cancelar esta liquidación?')">Cancelar liquidación</button>
        </form>
        """

    cancelado_info = ""
    if reembolso.estado == "cancelado":
        fecha_cancel = (
            reembolso.cancelado_en.strftime("%Y-%m-%d %H:%M")
            if reembolso.cancelado_en
            else "—"
        )
        cancelador_nombre = cancelador.nombre if cancelador else "—"
        cancelado_info = f"""
        <div class="notice warn" style="margin-top:12px;">
            <strong>Cancelada:</strong> {escape(fecha_cancel)} — por {escape(cancelador_nombre)}.
            <br><small>{escape(reembolso.motivo_cancelacion or '')}</small>
        </div>
        """

    actions_html = f"""
        <a href="/informes-de-gastos/{cuenta_id}" class="button secondary">Volver al informe</a>
    """
    side_html = f"""
        <div class="eyebrow">Estado</div>
        <div class="status-chip info" style="margin-top:6px;">{escape(estado_label)}</div>
        <div class="meta-grid">
            <div class="meta-card">
                <span>Monto</span>
                <strong>{format_currency(reembolso.monto)}</strong>
                <small>{escape(reembolso.moneda or 'MXN')}</small>
            </div>
            <div class="meta-card">
                <span>Fecha de pago</span>
                <strong>{escape(fecha_pago_str)}</strong>
            </div>
        </div>
    """

    html = f"""
    <!DOCTYPE html>
    <html>
    <head>
        <title>{escape(tipo_label)} — I-{escape(cuenta.referencia_base)}</title>
        <style>
            {_workspace_shell_styles("1024px")}
        </style>
    </head>
    <body>
        <div class="container">
            {render_top_navigation(current_empleado, "informes")}
            {_render_workspace_hero(
                eyebrow="Liquidación",
                title=escape(tipo_label),
                description=f"Cuenta I-{escape(cuenta.referencia_base)}",
                actions_html=actions_html,
                side_html=side_html,
            )}
            <div class="stack">
                <section class="surface">
                    <div class="section-head">
                        <div>
                            <h2>Detalle de la liquidación</h2>
                            <div class="section-note">Información capturada al registrar la liquidación.</div>
                        </div>
                    </div>
                    <div class="table-shell">
                        <table>
                            <tbody>
                                <tr><th>Tipo</th><td>{escape(tipo_label)}</td></tr>
                                <tr><th>Estado</th><td>{escape(estado_label)}</td></tr>
                                <tr><th>Monto</th><td>{format_currency(reembolso.monto)} {escape(reembolso.moneda or 'MXN')}</td></tr>
                                <tr><th>Método de pago</th><td>{escape((reembolso.metodo_pago or '—'))}</td></tr>
                                <tr><th>Fecha de pago</th><td>{escape(fecha_pago_str)}</td></tr>
                                <tr><th>Referencia</th><td>{escape(reembolso.referencia_pago or '—')}</td></tr>
                                <tr><th>Pagador</th><td>{escape(pagador_nombre)}</td></tr>
                                <tr><th>Notas</th><td>{escape(reembolso.notas or '—')}</td></tr>
                                <tr><th>Comprobantes</th><td>{adj_cell_html}</td></tr>
                            </tbody>
                        </table>
                    </div>
                    {cancelado_info}
                    {cancel_form}
                </section>
            </div>
        </div>
    </body>
    </html>
    """
    return html


@router.post(
    "/informes-de-gastos/{cuenta_id}/reembolsos/{reembolso_id}/cancelar"
)
async def cancelar_reembolso_cuenta(
    cuenta_id: UUIDType,
    reembolso_id: UUIDType,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
    motivo: str = Form(...),
) -> RedirectResponse:
    """Cancel a reembolso/devolucion. Finanzas / admin only."""
    try:
        await cancel_cuenta_settlement(
            session,
            cuenta_id=cuenta_id,
            reembolso_id=reembolso_id,
            actor_id=current_empleado.id,
            motivo=motivo,
        )
    except CuentaSettlementPermissionError as exc:
        raise HTTPException(status_code=403, detail=exc.message)
    except CuentaSettlementValidationError as exc:
        if exc.code in {"cuenta_not_found", "reembolso_not_found"}:
            raise HTTPException(status_code=404, detail=exc.message)
        return RedirectResponse(
            url=(
                f"/informes-de-gastos/{cuenta_id}/reembolsos/{reembolso_id}"
                f"?error={exc.code}&error_msg={quote(exc.message)}"
            ),
            status_code=303,
        )
    except Exception:
        await session.rollback()
        logger.exception(
            "Unexpected error cancelling cuenta settlement",
            extra={
                "cuenta_id": str(cuenta_id),
                "reembolso_id": str(reembolso_id),
                "actor_id": str(current_empleado.id),
            },
        )
        return RedirectResponse(
            url=(
                f"/informes-de-gastos/{cuenta_id}/reembolsos/{reembolso_id}"
                "?error=unexpected_cuenta_settlement_cancel&error_msg="
                + quote(
                    "Ocurrió un error al registrar la operación. Intente nuevamente."
                )
            ),
            status_code=303,
        )
    return RedirectResponse(
        url=(
            f"/informes-de-gastos/{cuenta_id}?success=cancelada"
            f"&msg={quote('Liquidación cancelada.')}"
        ),
        status_code=303,
    )


@router.get(
    "/informes-de-gastos/{cuenta_id}/reembolsos/{reembolso_id}/adjuntos/{adjunto_id}",
    response_model=None,
)
async def descargar_reembolso_adjunto(
    cuenta_id: UUIDType,
    reembolso_id: UUIDType,
    adjunto_id: UUIDType,
    session: AsyncSession = Depends(get_db_session),
    current_empleado: Empleado = Depends(get_current_empleado),
) -> Response:
    """Stream a comprobante attached to a reembolso/devolucion."""
    cuenta_result = await session.execute(
        select(CuentaDeGastos).where(CuentaDeGastos.id == cuenta_id)
    )
    cuenta = cuenta_result.scalar_one_or_none()
    if cuenta is None:
        raise HTTPException(status_code=404, detail="Informe de Gastos no encontrado")
    if not _can_access_reembolso_cuenta(cuenta, current_empleado):
        raise HTTPException(status_code=403, detail="Acceso denegado")

    reembolso_result = await session.execute(
        select(Reembolso).where(
            Reembolso.id == reembolso_id,
            Reembolso.cuenta_gastos_id == cuenta_id,
        )
    )
    reembolso = reembolso_result.scalar_one_or_none()
    if reembolso is None:
        raise HTTPException(status_code=404, detail="Liquidación no encontrada")

    adjunto = await fetch_adjunto_payload(
        session,
        adjunto_id=adjunto_id,
        reembolso_id=reembolso_id,
    )
    if not adjunto:
        raise HTTPException(status_code=404, detail="Adjunto no encontrado")
    try:
        raw, media_type, fname = await load_adjunto_payload_bytes(
            adjunto["ruta_archivo"],
            mime_hint=adjunto.get("mime_type") or adjunto.get("tipo_archivo"),
            nombre_archivo=adjunto.get("nombre_archivo"),
        )
    except ReceiptDecodeError as e:
        raise HTTPException(status_code=500, detail=str(e)) from e
    media_type, disposition = comprobante_response_headers(fname, media_type)
    return Response(
        content=raw,
        media_type=media_type,
        headers={"Content-Disposition": disposition},
    )
